window.TAILIEU_CARDS = [{"id": 1, "cat": "c1", "q": "Theo tài liệu tóm tắt Chương 1, từ nửa sau thế kỷ XIX, chủ nghĩa tư bản chuyển sang giai đoạn nào?", "options": ["A. Giai đoạn kinh tế tri thức", "B. Giai đoạn hậu công nghiệp", "C. Giai đoạn đế quốc chủ nghĩa", "D. Chủ nghĩa tư bản tự do cạnh tranh"], "answer": "C. Giai đoạn đế quốc chủ nghĩa", "letter": "C"}, {"id": 2, "cat": "c1", "q": "Hai cuộc khai thác thuộc địa của thực dân Pháp ở Việt Nam được tiến hành trong các khoảng thời gian nào?", "options": ["A. 1884–1896 và 1914–1918", "B. 1895–1910 và 1919–1935", "C. 1900–1918 và 1920–1930", "D. 1897–1914 và 1919–1929"], "answer": "D. 1897–1914 và 1919–1929", "letter": "D"}, {"id": 3, "cat": "c1", "q": "Dưới tác động của chính sách \"chia để trị\" và hai cuộc khai thác thuộc địa của Pháp, mâu thuẫn nào trở thành mâu thuẫn cơ bản, gay gắt nhất trong xã hội Việt Nam?", "options": ["A. Mâu thuẫn giữa nông dân với địa chủ phong kiến", "B. Mâu thuẫn giữa tư sản dân tộc với tư sản mại bản", "C. Mâu thuẫn giữa toàn thể dân tộc Việt Nam với thực dân Pháp", "D. Mâu thuẫn giữa tiểu tư sản với chế độ phong kiến"], "answer": "C. Mâu thuẫn giữa toàn thể dân tộc Việt Nam với thực dân Pháp", "letter": "C"}, {"id": 4, "cat": "c1", "q": "Nguyên nhân cốt lõi dẫn đến sự thất bại của các phong trào yêu nước theo khuynh hướng phong kiến (Cần Vương) và dân chủ tư sản đầu thế kỷ XX là gì?", "options": ["A. Các sĩ phu yêu nước không có tinh thần đấu tranh kiên quyết", "B. Thực dân Pháp nhận được viện trợ quân sự từ Mỹ", "C. Nhân dân không ủng hộ phong trào yêu nước", "D. Thiếu đường lối chính trị đúng đắn, chưa có giai cấp tiên phong lãnh đạo và phương pháp cách mạng chưa phù hợp"], "answer": "D. Thiếu đường lối chính trị đúng đắn, chưa có giai cấp tiên phong lãnh đạo và phương pháp cách mạng chưa phù hợp", "letter": "D"}, {"id": 5, "cat": "c1", "q": "Sự kiện nào vào tháng 12/1920 đánh dấu bước ngoặt tư tưởng đưa Nguyễn Ái Quốc trở thành người cộng sản Việt Nam đầu tiên?", "options": ["A. Bỏ phiếu tán thành gia nhập Quốc tế Cộng sản tại Đại hội Tours và tham gia sáng lập Đảng Cộng sản Pháp", "B. Thành lập Hội Việt Nam Cách mạng Thanh niên tại Quảng Châu", "C. Gửi bản Yêu sách của nhân dân An Nam đến Hội nghị Vécxây", "D. Ra đi tìm đường cứu nước tại bến Nhà Rồng"], "answer": "A. Bỏ phiếu tán thành gia nhập Quốc tế Cộng sản tại Đại hội Tours và tham gia sáng lập Đảng Cộng sản Pháp", "letter": "A"}, {"id": 6, "cat": "c1", "q": "Tác phẩm \"Bản án chế độ thực dân Pháp\" được Nguyễn Ái Quốc xuất bản vào năm nào?", "options": ["A. Năm 1925", "B. Năm 1922", "C. Năm 1920", "D. Năm 1927"], "answer": "A. Năm 1925", "letter": "A"}, {"id": 7, "cat": "c1", "q": "Tác phẩm \"Đường Kách mệnh\" được Nguyễn Ái Quốc biên soạn vào năm nào để truyền bá chủ nghĩa Mác – Lênin về nước?", "options": ["A. Năm 1929", "B. Năm 1925", "C. Năm 1924", "D. Năm 1927"], "answer": "D. Năm 1927", "letter": "D"}, {"id": 8, "cat": "c1", "q": "Theo tài liệu tóm tắt Chương 1, thứ tự thời gian ra đời của ba tổ chức cộng sản tại Việt Nam năm 1929 là gì?", "options": ["A. An Nam Cộng sản Đảng (6/1929), Đông Dương Cộng sản Đảng (9/1929), Đông Dương Cộng sản Liên đoàn (11/1929)", "B. Đông Dương Cộng sản Đảng (3/1929), An Nam Cộng sản Đảng (8/1929), Đông Dương Cộng sản Liên đoàn (12/1929)", "C. Đông Dương Cộng sản Đảng (6/1929), Đông Dương Cộng sản Liên đoàn (9/1929), An Nam Cộng sản Đảng (11/1929)", "D. Đông Dương Cộng sản Liên đoàn (6/1929), Đông Dương Cộng sản Đảng (9/1929), An Nam Cộng sản Đảng (11/1929)"], "answer": "C. Đông Dương Cộng sản Đảng (6/1929), Đông Dương Cộng sản Liên đoàn (9/1929), An Nam Cộng sản Đảng (11/1929)", "letter": "C"}, {"id": 9, "cat": "c1", "q": "Hội nghị hợp nhất thành lập Đảng Cộng sản Việt Nam tại Cửu Long (Hương Cảng, Trung Quốc) diễn ra trong khoảng thời gian nào?", "options": ["A. Từ ngày 6/1 đến 7/2/1930", "B. Từ ngày 3/1 đến 3/2/1930", "C. Từ ngày 1/2 đến 8/2/1930", "D. Từ ngày 10/1 đến 15/2/1930"], "answer": "A. Từ ngày 6/1 đến 7/2/1930", "letter": "A"}, {"id": 10, "cat": "c1", "q": "Nguyễn Ái Quốc chủ trì Hội nghị hợp nhất thành lập Đảng Cộng sản Việt Nam đầu năm 1930 với tư cách gì?", "options": ["A. Tổng Bí thư lâm thời của Đảng", "B. Phái viên của Quốc tế Cộng sản", "C. Chủ tịch Hội Việt Nam Cách mạng Thanh niên", "D. Đại biểu của Đông Dương Cộng sản Đảng"], "answer": "B. Phái viên của Quốc tế Cộng sản", "letter": "B"}, {"id": 11, "cat": "c1", "q": "Bốn văn kiện do Nguyễn Ái Quốc soạn thảo được thông qua tại Hội nghị thành lập Đảng Cộng sản Việt Nam (2/1930) là gì?", "options": ["A. Chánh cương vắn tắt, Luận cương chính trị, Sách lược vắn tắt, Chương trình hành động", "B. Luận cương chính trị, Chánh cương vắn tắt, Điều lệ tóm tắt, Lời kêu gọi", "C. Chánh cương vắn tắt, Sách lược vắn tắt, Chương trình tóm tắt, Điều lệ vắn tắt", "D. Đường Kách mệnh, Chánh cương vắn tắt, Sách lược vắn tắt, Điều lệ Đảng"], "answer": "C. Chánh cương vắn tắt, Sách lược vắn tắt, Chương trình tóm tắt, Điều lệ vắn tắt", "letter": "C"}, {"id": 12, "cat": "c1", "q": "Về nhiệm vụ kinh tế, Cương lĩnh chính trị đầu tiên của Đảng (2/1930) chủ trương nội dung nào sau đây?", "options": ["A. Chỉ cải cách giảm tô, giảm tức mà không tịch thu sản nghiệp đế quốc", "B. Tịch thu sản nghiệp lớn của đế quốc, chia ruộng đất cho dân cày nghèo, bỏ sưu thuế", "C. Quốc hữu hóa toàn bộ ruộng đất của cả nông dân và địa chủ", "D. Phát triển kinh tế thị trường nhiều thành phần định hướng xã hội chủ nghĩa"], "answer": "B. Tịch thu sản nghiệp lớn của đế quốc, chia ruộng đất cho dân cày nghèo, bỏ sưu thuế", "letter": "B"}, {"id": 13, "cat": "c1", "q": "Về nhiệm vụ xã hội, Cương lĩnh chính trị đầu tiên của Đảng (2/1930) xác định chủ trương nào?", "options": ["A. Xây dựng nền văn hóa tiên tiến, đậm đà bản sắc dân tộc", "B. Chỉ mở trường học cho con em giai cấp công nhân", "C. Nam nữ bình quyền, phổ thông giáo dục theo công nông hóa", "D. Phát triển giáo dục đại học và khoa học công nghệ làm quốc sách hàng đầu"], "answer": "C. Nam nữ bình quyền, phổ thông giáo dục theo công nông hóa", "letter": "C"}, {"id": 14, "cat": "c1", "q": "Trong Cương lĩnh chính trị đầu tiên (2/1930), Đảng chủ trương đối sách như thế nào đối với phú nông, trung – tiểu địa chủ và tư bản An Nam?", "options": ["A. Đứng ngoài mặt trận dân tộc thống nhất và không tiếp xúc", "B. Xác định họ là lực lượng lãnh đạo cách mạng", "C. Lợi dụng hoặc trung lập", "D. Đánh đổ hoàn toàn như đế quốc xâm lược"], "answer": "C. Lợi dụng hoặc trung lập", "letter": "C"}, {"id": 15, "cat": "c1", "q": "Phương pháp cách mạng được xác định trong Cương lĩnh chính trị đầu tiên của Đảng (2/1930) là gì?", "options": ["A. Thương lượng từng bước với chính quyền thực dân Pháp", "B. Chỉ sử dụng đấu tranh ngoại giao nhờ sự giúp đỡ của quốc tế", "C. Bạo lực cách mạng của quần chúng, không bao giờ thỏa hiệp", "D. Đấu tranh nghị trường và cải cách hòa bình"], "answer": "C. Bạo lực cách mạng của quần chúng, không bao giờ thỏa hiệp", "letter": "C"}, {"id": 16, "cat": "c1", "q": "Vai trò lãnh đạo của Đảng được nêu trong Cương lĩnh chính trị đầu tiên (2/1930) là gì?", "options": ["A. Đảng là tổ chức liên minh giữa tư sản dân tộc và địa chủ yêu nước", "B. Đảng là đội tiên phong của vô sản giai cấp, phải làm cho giai cấp mình lãnh đạo được dân chúng", "C. Đảng là cơ quan hành chính tối cao của Nhà nước", "D. Đảng chỉ đại diện cho lợi ích riêng của tầng lớp trí thức"], "answer": "B. Đảng là đội tiên phong của vô sản giai cấp, phải làm cho giai cấp mình lãnh đạo được dân chúng", "letter": "B"}, {"id": 17, "cat": "c1", "q": "Theo tài liệu Chương 1, nguyên nhân nào dẫn đến những hạn chế trong Luận cương chính trị tháng 10/1930?", "options": ["A. Do thiếu sự tham gia của giai cấp công nhân", "B. Do chịu ảnh hưởng của tư tưởng \"tả\" khuynh", "C. Do Đảng chưa có hệ thống tổ chức ở địa phương", "D. Do chịu ảnh hưởng của khuynh hướng dân chủ tư sản"], "answer": "B. Do chịu ảnh hưởng của tư tưởng \"tả\" khuynh", "letter": "B"}, {"id": 18, "cat": "c1", "q": "Chính quyền Xô viết được thành lập tại một số xã ở Nghệ An và Hà Tĩnh trong cao trào 1930–1931 mang ý nghĩa lịch sử gì?", "options": ["A. Hình thức chính quyền công nông đầu tiên ở Việt Nam", "B. Chính quyền tự trị thuộc khối Liên hiệp Pháp", "C. Chính phủ lâm thời của nước Việt Nam Dân chủ Cộng hòa", "D. Hình thức chính quyền liên hiệp với tư sản dân tộc đầu tiên ở Việt Nam"], "answer": "A. Hình thức chính quyền công nông đầu tiên ở Việt Nam", "letter": "A"}, {"id": 19, "cat": "c1", "q": "Để từng bước khôi phục hệ thống tổ chức và phong trào quần chúng sau khủng bố trắng, năm 1932 Đảng đã công bố văn kiện nào?", "options": ["A. Chỉ thị Kháng chiến kiến quốc", "B. Đề cương về văn hóa Việt Nam", "C. Luận cương chính trị", "D. Chương trình hành động của Đảng"], "answer": "D. Chương trình hành động của Đảng", "letter": "D"}, {"id": 20, "cat": "c1", "q": "Đại hội đại biểu toàn quốc lần thứ I của Đảng (3/1935) được tổ chức tại đâu và có ý nghĩa gì?", "options": ["A. Tại Pác Bó (Cao Bằng) — hoàn chỉnh chuyển hướng chiến lược giải phóng dân tộc", "B. Tại Cửu Long (Hương Cảng) — thông qua Cương lĩnh đầu tiên", "C. Tại Ma Cao (Trung Quốc) — đánh dấu sự phục hồi hệ thống tổ chức của Đảng và phong trào quần chúng", "D. Tại Chiêm Hóa (Tuyên Quang) — đưa Đảng ra hoạt động công khai"], "answer": "C. Tại Ma Cao (Trung Quốc) — đánh dấu sự phục hồi hệ thống tổ chức của Đảng và phong trào quần chúng", "letter": "C"}, {"id": 21, "cat": "c1", "q": "Trong phong trào dân chủ 1936–1939, Đảng chủ trương tạm gác hai khẩu hiệu nào?", "options": ["A. \"Độc lập dân tộc\" và \"Cách mạng ruộng đất\"", "B. \"Tự do dân chủ\" và \"Cơm áo hòa bình\"", "C. \"Chống phát xít\" và \"Chống chiến tranh\"", "D. \"Đoàn kết công nông\" và \"Đấu tranh báo chí\""], "answer": "A. \"Độc lập dân tộc\" và \"Cách mạng ruộng đất\"", "letter": "A"}, {"id": 22, "cat": "c1", "q": "Ý nghĩa lịch sử của phong trào dân chủ 1936–1939 đối với Cách mạng Tháng Tám 1945 là gì?", "options": ["A. Là cuộc tổng diễn tập đầu tiên chuẩn bị cho Cách mạng Tháng Tám", "B. Là cuộc tổng diễn tập thứ hai chuẩn bị cho Cách mạng Tháng Tám; tôi luyện cán bộ, mở rộng ảnh hưởng quần chúng", "C. Đánh đổ hoàn toàn chế độ thực dân Pháp ở Đông Dương", "D. Thành lập chính quyền Xô viết trên phạm vi cả nước"], "answer": "B. Là cuộc tổng diễn tập thứ hai chuẩn bị cho Cách mạng Tháng Tám; tôi luyện cán bộ, mở rộng ảnh hưởng quần chúng", "letter": "B"}, {"id": 23, "cat": "c1", "q": "Sự kiện nào vào tháng 9/1940 đẩy nhân dân Việt Nam vào cảnh \"một cổ hai tròng\"?", "options": ["A. Chiến tranh thế giới thứ hai bùng nổ ở châu Âu", "B. Phát xít Nhật tiến vào Đông Dương", "C. Quân Trung Hoa Dân quốc kéo vào miền Bắc Việt Nam", "D. Nhật đảo chính Pháp độc chiếm Đông Dương"], "answer": "B. Phát xít Nhật tiến vào Đông Dương", "letter": "B"}, {"id": 24, "cat": "c1", "q": "Mặt trận Việt Nam Độc lập Đồng minh (Mặt trận Việt Minh) được thành lập vào ngày tháng năm nào?", "options": ["A. Ngày 12/3/1941", "B. Ngày 19/5/1941", "C. Ngày 13/8/1945", "D. Ngày 22/12/1944"], "answer": "B. Ngày 19/5/1941", "letter": "B"}, {"id": 25, "cat": "c1", "q": "Hội nghị Trung ương 8 (5/1941) do lãnh tụ Nguyễn Ái Quốc chủ trì được tổ chức tại địa điểm nào?", "options": ["A. Pác Bó (Cao Bằng)", "B. Bà Điểm (Hóc Môn, Gia Định)", "C. Đình Bảng (Bắc Ninh)", "D. Tân Trào (Tuyên Quang)"], "answer": "A. Pác Bó (Cao Bằng)", "letter": "A"}, {"id": 26, "cat": "c1", "q": "Ngày 22/12/1944 gắn với sự kiện lịch sử trọng đại nào?", "options": ["A. Thành lập Ủy ban Khởi nghĩa toàn quốc", "B. Ban hành Đề cương về văn hóa Việt Nam", "C. Thành lập Đội Việt Nam Tuyên truyền Giải phóng quân — tiền thân của Quân đội nhân dân Việt Nam", "D. Phát động cao trào kháng Nhật cứu nước"], "answer": "C. Thành lập Đội Việt Nam Tuyên truyền Giải phóng quân — tiền thân của Quân đội nhân dân Việt Nam", "letter": "C"}, {"id": 27, "cat": "c1", "q": "Chỉ thị \"Nhật – Pháp bắn nhau và hành động của chúng ta\" (12/3/1945) của Ban Thường vụ Trung ương Đảng đã phát động phong trào nào?", "options": ["A. Phong trào Bình dân học vụ", "B. Cao trào kháng Nhật cứu nước", "C. Phong trào Đồng khởi", "D. Phong trào Đông Dương Đại hội"], "answer": "B. Cao trào kháng Nhật cứu nước", "letter": "B"}, {"id": 28, "cat": "c1", "q": "Ngày 13/8/1945, Ủy ban Khởi nghĩa toàn quốc được thành lập và đến 23 giờ cùng ngày đã ban bố văn kiện nào?", "options": ["A. Lời kêu gọi toàn quốc kháng chiến", "B. Tuyên ngôn Độc lập", "C. Quân lệnh số 1 phát lệnh Tổng khởi nghĩa", "D. Chỉ thị Kháng chiến kiến quốc"], "answer": "C. Quân lệnh số 1 phát lệnh Tổng khởi nghĩa", "letter": "C"}, {"id": 29, "cat": "c1", "q": "Hội nghị toàn quốc của Đảng và Đại hội Quốc dân Tân Trào quyết định phát động Tổng khởi nghĩa tháng Tám năm 1945 diễn ra vào thời gian nào?", "options": ["A. Ngày 9–12/8/1945 và ngày 13/8/1945", "B. Ngày 14–15/8/1945 và ngày 16/8/1945", "C. Ngày 20–22/8/1945 và ngày 25/8/1945", "D. Ngày 17–18/8/1945 và ngày 19/8/1945"], "answer": "B. Ngày 14–15/8/1945 và ngày 16/8/1945", "letter": "B"}, {"id": 30, "cat": "c1", "q": "Theo tài liệu Chương 1, tính chất của Cách mạng Tháng Tám năm 1945 là gì?", "options": ["A. Cuộc cách mạng tư sản dân quyền cũ do giai cấp tư sản lãnh đạo", "B. Cuộc cách mạng giải phóng dân tộc điển hình, mang tính chất dân chủ mới, do giai cấp công nhân lãnh đạo, dựa trên lực lượng toàn dân và mang tính nhân dân sâu sắc", "C. Cuộc cách mạng xã hội chủ nghĩa thuần túy ở vùng nông thôn", "D. Cuộc đảo chính quân sự giành chính quyền từ tay phát xít Nhật"], "answer": "B. Cuộc cách mạng giải phóng dân tộc điển hình, mang tính chất dân chủ mới, do giai cấp công nhân lãnh đạo, dựa trên lực lượng toàn dân và mang tính nhân dân sâu sắc", "letter": "B"}, {"id": 31, "cat": "c2", "q": "Ngay sau Cách mạng Tháng Tám 1945, lực lượng quân đội nước ngoài nào đã kéo vào miền Bắc Việt Nam kèm theo các tổ chức phản động Việt Quốc, Việt Cách?", "options": ["A. 20 vạn quân Trung Hoa Dân quốc (quân Tưởng)", "B. 10 vạn quân Anh", "C. 15 vạn quân Mỹ", "D. 20 vạn quân Pháp"], "answer": "A. 20 vạn quân Trung Hoa Dân quốc (quân Tưởng)", "letter": "A"}, {"id": 32, "cat": "c2", "q": "Chỉ thị \"Kháng chiến kiến quốc\" ngày 25/11/1945 của Ban Chấp hành Trung ương Đảng đề ra 4 nhiệm vụ trước mắt là gì?", "options": ["A. Cải cách ruộng đất, công nghiệp hóa, quốc hữu hóa và hợp tác xã hóa", "B. Xây dựng kinh tế thị trường, mở cửa đối ngoại, gia nhập Liên Hợp Quốc, xóa mù chữ", "C. Củng cố chính quyền, chống thực dân Pháp xâm lược, bài trừ nội phản, cải thiện đời sống nhân dân", "D. Đánh đuổi quân Tưởng, đánh đuổi quân Anh, mở chiến dịch Điện Biên Phủ, ký Hiệp định Giơnevơ"], "answer": "C. Củng cố chính quyền, chống thực dân Pháp xâm lược, bài trừ nội phản, cải thiện đời sống nhân dân", "letter": "C"}, {"id": 33, "cat": "c2", "q": "Để chống \"giặc đói\" ngay sau Cách mạng Tháng Tám 1945, Đảng và Chính phủ đã phát động phong trào nào?", "options": ["A. \"Bình dân học vụ\" và \"Tuần lễ vàng\"", "B. \"Khoán 100\" và \"Khoán 10\"", "C. \"Tăng gia sản xuất ngay, tăng gia sản xuất nữa\", \"Hũ gạo tiết kiệm\", \"Ngày đồng tâm\"", "D. \"Ba sẵn sàng\" và \"Ba đảm đang\""], "answer": "C. \"Tăng gia sản xuất ngay, tăng gia sản xuất nữa\", \"Hũ gạo tiết kiệm\", \"Ngày đồng tâm\"", "letter": "C"}, {"id": 34, "cat": "c2", "q": "Để giải quyết khó khăn về tài chính sau Cách mạng Tháng Tám 1945, Chính phủ đã thành lập \"Quỹ Độc lập\" và tổ chức \"Tuần lễ vàng\" vào thời gian nào?", "options": ["A. Quỹ Độc lập (23/9/1945) và Tuần lễ vàng (1–7/10/1945)", "B. Quỹ Độc lập (4/9/1945) và Tuần lễ vàng (17–24/9/1945)", "C. Quỹ Độc lập (2/9/1945) và Tuần lễ vàng (5–12/9/1945)", "D. Quỹ Độc lập (11/11/1945) và Tuần lễ vàng (25/11–2/12/1945)"], "answer": "B. Quỹ Độc lập (4/9/1945) và Tuần lễ vàng (17–24/9/1945)", "letter": "B"}, {"id": 35, "cat": "c2", "q": "Kết quả của phong trào \"Bình dân học vụ\" tính đến cuối năm 1946 là gì?", "options": ["A. Có hơn 500 nghìn người biết đọc, biết viết", "B. Có hơn 2,5 triệu người biết đọc, biết viết", "C. Xóa mù chữ hoàn toàn 100% dân số cả nước", "D. Có hơn 10 triệu người tốt nghiệp tiểu học"], "answer": "B. Có hơn 2,5 triệu người biết đọc, biết viết", "letter": "B"}, {"id": 36, "cat": "c2", "q": "Cuộc Tổng tuyển cử bầu Quốc hội khóa I và việc thông qua bản Hiến pháp đầu tiên của nước Việt Nam Dân chủ Cộng hòa diễn ra vào thời gian nào?", "options": ["A. Tổng tuyển cử 6/3/1946 và Hiến pháp tháng 12/1946", "B. Tổng tuyển cử 2/9/1945 và Hiến pháp tháng 3/1946", "C. Tổng tuyển cử 6/1/1946 và Hiến pháp tháng 11/1946", "D. Tổng tuyển cử 19/5/1946 và Hiến pháp tháng 9/1946"], "answer": "C. Tổng tuyển cử 6/1/1946 và Hiến pháp tháng 11/1946", "letter": "C"}, {"id": 37, "cat": "c2", "q": "Mục đích chiến lược của việc Chính phủ ta ký Hiệp định Sơ bộ (6/3/1946) và Tạm ước (14/9/1946) với thực dân Pháp là gì?", "options": ["A. Công nhận nền thống trị lâu dài của thực dân Pháp trên toàn cõi Đông Dương", "B. Chấm dứt hoàn toàn chiến tranh và tiến hành tổng tuyển cử thống nhất đất nước", "C. Xin gia nhập khối Liên hiệp Pháp để nhận viện trợ kinh tế", "D. Đuổi quân Tưởng về nước, tránh cùng lúc đối phó nhiều kẻ thù và tranh thủ thời gian hòa bình chuẩn bị lực lượng kháng chiến lâu dài"], "answer": "D. Đuổi quân Tưởng về nước, tránh cùng lúc đối phó nhiều kẻ thù và tranh thủ thời gian hòa bình chuẩn bị lực lượng kháng chiến lâu dài", "letter": "D"}, {"id": 38, "cat": "c2", "q": "Trong xây dựng căn cứ địa và hậu phương kháng chiến chống Pháp (1946–1950), Đảng thực hiện chủ trương nào để làm thất bại âm mưu lấy chiến tranh nuôi chiến tranh của địch?", "options": ["A. \"Vườn không nhà trống\" chỉ ở các đô thị miền Nam", "B. \"Chiến tranh chớp nhoáng\"", "C. Tạm dừng sản xuất nông nghiệp để tập trung toàn bộ cho quân sự", "D. \"Tiêu thổ kháng chiến\", rút các cơ quan Trung ương lên chiến khu Việt Bắc"], "answer": "D. \"Tiêu thổ kháng chiến\", rút các cơ quan Trung ương lên chiến khu Việt Bắc", "letter": "D"}, {"id": 39, "cat": "c2", "q": "Lực lượng vũ trang \"ba thứ quân\" được Đảng ta xây dựng trong cuộc kháng chiến chống Pháp gồm những lực lượng nào?", "options": ["A. Quân chính quy, thanh niên xung phong, dân công hỏa tuyến", "B. Bộ đội chủ lực, bộ đội địa phương, dân quân du kích", "C. Công an nhân dân, bộ đội biên phòng, tự vệ đô thị", "D. Lục quân, hải quân, không quân"], "answer": "B. Bộ đội chủ lực, bộ đội địa phương, dân quân du kích", "letter": "B"}, {"id": 40, "cat": "c2", "q": "Chiến thắng Biên giới Thu – Đông năm 1950 có ý nghĩa chiến lược quan trọng nào đối với cuộc kháng chiến chống Pháp?", "options": ["A. Khai thông đường liên lạc quốc tế và giành quyền chủ động chiến lược trên chiến trường chính Bắc Bộ", "B. Buộc thực dân Pháp phải ký Hiệp định Giơnevơ", "C. Đập tan hoàn toàn kế hoạch quân sự Nava", "D. Đánh bại hoàn toàn kế hoạch \"đánh nhanh thắng nhanh\" của Pháp"], "answer": "A. Khai thông đường liên lạc quốc tế và giành quyền chủ động chiến lược trên chiến trường chính Bắc Bộ", "letter": "A"}, {"id": 41, "cat": "c2", "q": "Từ cuối năm 1950 đến giữa năm 1953, quân và dân ta liên tiếp mở các chiến dịch nào để giữ vững và phát triển quyền chủ động chiến lược trên chiến trường chính Bắc Bộ?", "options": ["A. Việt Bắc, Biên giới, Đồng Khởi, Mậu Thân", "B. Tây Nguyên, Huế – Đà Nẵng, Phước Long, Hồ Chí Minh", "C. Ấp Bắc, Bình Giã, Vạn Tường, Plâyme", "D. Trung Du, Đường 18, Hà Nam Ninh, Hòa Bình, Tây Bắc, Thượng Lào"], "answer": "D. Trung Du, Đường 18, Hà Nam Ninh, Hòa Bình, Tây Bắc, Thượng Lào", "letter": "D"}, {"id": 42, "cat": "c2", "q": "Chiến dịch Điện Biên Phủ diễn ra trong khoảng thời gian nào và trải qua mấy đợt tiến công liên tục?", "options": ["A. Từ 19/12/1953 đến 1/5/1954, trải qua 2 đợt", "B. Từ 13/3 đến 7/5/1954, trải qua 3 đợt tiến công liên tục", "C. Từ 7/3 đến 21/7/1954, trải qua 3 đợt tiến công", "D. Từ 1/3 đến 19/5/1954, trải qua 4 đợt tiến công"], "answer": "B. Từ 13/3 đến 7/5/1954, trải qua 3 đợt tiến công liên tục", "letter": "B"}, {"id": 43, "cat": "c2", "q": "Hiệp định Genève về chấm dứt chiến tranh, lập lại hòa bình ở Đông Dương được ký kết vào ngày tháng năm nào?", "options": ["A. Ngày 21/7/1954", "B. Ngày 27/1/1954", "C. Ngày 7/5/1954", "D. Ngày 8/5/1954"], "answer": "A. Ngày 21/7/1954", "letter": "A"}, {"id": 44, "cat": "c2", "q": "Theo nội dung Hiệp định Genève (21/7/1954), vĩ tuyến 17 được quy định với tính chất như thế nào?", "options": ["A. Là giới tuyến quân sự tạm thời để hai bên tập kết, chuyển quân; hoàn toàn không phải là biên giới chính trị hay lãnh thổ", "B. Là biên giới chính trị và lãnh thổ vĩnh viễn chia cắt hai quốc gia", "C. Là ranh giới hành chính giữa miền Bắc và miền Trung", "D. Là khu vực do quân đội Liên Hợp Quốc quản lý lâu dài"], "answer": "A. Là giới tuyến quân sự tạm thời để hai bên tập kết, chuyển quân; hoàn toàn không phải là biên giới chính trị hay lãnh thổ", "letter": "A"}, {"id": 45, "cat": "c1", "q": "Ý nghĩa quốc tế lớn lao của thắng lợi cuộc kháng chiến chống thực dân Pháp (1945–1954) là gì?", "options": ["A. Thành lập hệ thống xã hội chủ nghĩa trên toàn châu Á", "B. Giáng đòn mạnh vào hệ thống thuộc địa của chủ nghĩa đế quốc, cổ vũ mạnh mẽ phong trào giải phóng dân tộc trên thế giới, nhất là ở châu Á, châu Phi", "C. Buộc Mỹ phải rút quân khỏi toàn bộ khu vực Đông Nam Á", "D. Chấm dứt hoàn toàn sự tồn tại của chủ nghĩa tư bản ở châu Âu"], "answer": "B. Giáng đòn mạnh vào hệ thống thuộc địa của chủ nghĩa đế quốc, cổ vũ mạnh mẽ phong trào giải phóng dân tộc trên thế giới, nhất là ở châu Á, châu Phi", "letter": "B"}, {"id": 46, "cat": "c2", "q": "Trong các năm 1956–1957, cùng với khôi phục kinh tế, miền Bắc đã kiên quyết thực hiện nhiệm vụ gì trong lĩnh vực nông nghiệp?", "options": ["A. Bắt đầu xuất khẩu gạo ra thị trường thế giới", "B. Hoàn thành cải cách ruộng đất đồng thời kiên quyết sửa chữa những sai lầm trong cải cách ruộng đất", "C. Thực hiện Khoán 100 và Khoán 10", "D. Xóa bỏ hoàn toàn sở hữu ruộng đất của nông dân"], "answer": "B. Hoàn thành cải cách ruộng đất đồng thời kiên quyết sửa chữa những sai lầm trong cải cách ruộng đất", "letter": "B"}, {"id": 47, "cat": "c2", "q": "Phong trào Đồng khởi ở miền Nam (1959–1960) đạt đỉnh cao với cuộc Đồng khởi Bến Tre nổ ra vào ngày tháng năm nào?", "options": ["A. Ngày 20/12/1960", "B. Ngày 10/5/1959", "C. Ngày 1/1/1959", "D. Ngày 17/1/1960"], "answer": "D. Ngày 17/1/1960", "letter": "D"}, {"id": 48, "cat": "c2", "q": "Mặt trận Dân tộc Giải phóng miền Nam Việt Nam chính thức ra đời vào ngày tháng năm nào?", "options": ["A. Ngày 20/12/1960", "B. Ngày 17/1/1960", "C. Ngày 5/9/1960", "D. Ngày 2/9/1960"], "answer": "A. Ngày 20/12/1960", "letter": "A"}, {"id": 49, "cat": "c2", "q": "Hai chiến thắng tiêu biểu nào góp phần đánh bại chiến lược \"Chiến tranh đặc biệt\" (1961–1965) của đế quốc Mỹ ở miền Nam?", "options": ["A. Vạn Tường (1965) và Plâyme (1965)", "B. Việt Bắc (1947) và Biên giới (1950)", "C. Phước Long (1975) và Buôn Ma Thuột (1975)", "D. Ấp Bắc (1963) và Bình Giã (1964–1965)"], "answer": "D. Ấp Bắc (1963) và Bình Giã (1964–1965)", "letter": "D"}, {"id": 50, "cat": "c2", "q": "Hai tuyến chi viện chiến lược huyết mạch từ hậu phương miền Bắc vào tiền tuyến miền Nam được thành lập vào những năm nào?", "options": ["A. Đường Trường Sơn (Đường 559) năm 1960 và Đường vận tải biển (Đường 759) năm 1965", "B. Đường Trường Sơn (Đường 559) năm 1961 và Đường vận tải biển (Đường 759) năm 1963", "C. Đường Trường Sơn (Đường 559) năm 1959 và Đường vận tải biển (Đường 759) năm 1961", "D. Đường Trường Sơn (Đường 559) năm 1955 và Đường vận tải biển (Đường 759) năm 1959"], "answer": "C. Đường Trường Sơn (Đường 559) năm 1959 và Đường vận tải biển (Đường 759) năm 1961", "letter": "C"}, {"id": 51, "cat": "c2", "q": "Hai chiến thắng tiêu biểu nào của quân dân miền Nam trong giai đoạn đánh bại chiến lược \"Chiến tranh cục bộ\" (1965–1968) của Mỹ?", "options": ["A. Phước Long và Xuân Lộc", "B. Đông Khê và Thất Khê", "C. Vạn Tường và Plâyme", "D. Ấp Bắc và Bình Giã"], "answer": "C. Vạn Tường và Plâyme", "letter": "C"}, {"id": 52, "cat": "c2", "q": "Ở hậu phương miền Bắc trong thời kỳ chống Mỹ (1965–1975), phong trào thi đua \"Ba sẵn sàng\" và \"Ba đảm đang\" được phát động tương ứng trong lực lượng nào?", "options": ["A. \"Ba sẵn sàng\" trong công nhân, \"Ba đảm đang\" trong nông dân", "B. \"Ba sẵn sàng\" trong thanh niên, \"Ba đảm đang\" trong phụ nữ", "C. \"Ba sẵn sàng\" trong trí thức, \"Ba đảm đang\" trong bộ đội", "D. \"Ba sẵn sàng\" trong phụ nữ, \"Ba đảm đang\" trong thanh niên"], "answer": "B. \"Ba sẵn sàng\" trong thanh niên, \"Ba đảm đang\" trong phụ nữ", "letter": "B"}, {"id": 53, "cat": "c2", "q": "Các phong trào \"Tay cày tay súng\", \"Tay búa tay súng\" ở miền Bắc giai đoạn 1965–1975 thể hiện tinh thần gì?", "options": ["A. Tạm dừng sản xuất để toàn dân nhập ngũ", "B. Vừa đẩy mạnh sản xuất, vừa sẵn sàng chiến đấu và chi viện tiền tuyến", "C. Đấu tranh nghị trường và báo chí công khai", "D. Tập trung xây dựng công nghiệp nặng tại vùng giải phóng miền Nam"], "answer": "B. Vừa đẩy mạnh sản xuất, vừa sẵn sàng chiến đấu và chi viện tiền tuyến", "letter": "B"}, {"id": 54, "cat": "c2", "q": "Cuộc Tổng tiến công và nổi dậy Tết Mậu Thân 1968 đã tạo ra bước ngoặt nào trên mặt trận quân sự và ngoại giao?", "options": ["A. Buộc Pháp rút quân hoàn toàn khỏi Đông Dương", "B. Giải phóng hoàn toàn miền Nam, chấm dứt chiến tranh ngay trong năm 1968", "C. Giáng đòn quyết định vào ý chí xâm lược của Mỹ, buộc Mỹ xuống thang chiến tranh, chấm dứt ném bom miền Bắc, ngồi vào bàn đàm phán bốn bên tại Paris (1968) và chuyển sang \"Việt Nam hóa chiến tranh\"", "D. Làm phá sản chiến lược \"Chiến tranh đơn phương\" của Mỹ – Diệm"], "answer": "C. Giáng đòn quyết định vào ý chí xâm lược của Mỹ, buộc Mỹ xuống thang chiến tranh, chấm dứt ném bom miền Bắc, ngồi vào bàn đàm phán bốn bên tại Paris (1968) và chuyển sang \"Việt Nam hóa chiến tranh\"", "letter": "C"}, {"id": 55, "cat": "c2", "q": "Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam được thành lập vào thời gian nào?", "options": ["A. Tháng 6/1969", "B. Tháng 12/1960", "C. Tháng 1/1968", "D. Tháng 1/1973"], "answer": "A. Tháng 6/1969", "letter": "A"}, {"id": 56, "cat": "c2", "q": "Thắng lợi nào vào tháng 12/1972 đã đánh bại cuộc tập kích chiến lược bằng máy bay B-52 của Mỹ vào Hà Nội, Hải Phòng, buộc Mỹ phải ký Hiệp định Paris?", "options": ["A. Chiến thắng Vạn Tường", "B. Chiến dịch Đường 9 – Nam Lào", "C. Chiến dịch Tây Nguyên", "D. Chiến thắng \"Điện Biên Phủ trên không\""], "answer": "D. Chiến thắng \"Điện Biên Phủ trên không\"", "letter": "D"}, {"id": 57, "cat": "c2", "q": "Hiệp định Paris về chấm dứt chiến tranh, lập lại hòa bình ở Việt Nam được ký kết vào ngày tháng năm nào?", "options": ["A. Ngày 21/7/1972", "B. Ngày 29/12/1972", "C. Ngày 27/1/1973", "D. Ngày 30/4/1973"], "answer": "C. Ngày 27/1/1973", "letter": "C"}, {"id": 58, "cat": "c2", "q": "Sau Hiệp định Paris (1/1973), Nghị quyết Hội nghị Trung ương 21 (7/1973) khẳng định con đường cách mạng miền Nam vẫn là gì?", "options": ["A. Con đường bạo lực cách mạng", "B. Đấu tranh hòa bình, nghị trường bằng mọi giá", "C. Tạm gác đấu tranh vũ trang để khôi phục kinh tế", "D. Chờ đợi sự can thiệp của Hội đồng Bảo an Liên Hợp Quốc"], "answer": "A. Con đường bạo lực cách mạng", "letter": "A"}, {"id": 59, "cat": "c2", "q": "Cuộc Tổng tiến công và nổi dậy mùa Xuân năm 1975 diễn ra qua ba chiến dịch lớn theo trình tự nào?", "options": ["A. Đường 9 – Nam Lào → Huế – Đà Nẵng → Chiến dịch Hồ Chí Minh", "B. Tây Nguyên → Huế – Đà Nẵng → Chiến dịch Hồ Chí Minh", "C. Huế – Đà Nẵng → Tây Nguyên → Chiến dịch Hồ Chí Minh", "D. Phước Long → Tây Nguyên → Hồ Chí Minh"], "answer": "B. Tây Nguyên → Huế – Đà Nẵng → Chiến dịch Hồ Chí Minh", "letter": "B"}, {"id": 60, "cat": "c2", "q": "Chiến dịch Tây Nguyên mở màn cho cuộc Tổng tiến công và nổi dậy mùa Xuân 1975 bắt đầu bằng trận đánh then chốt nào?", "options": ["A. Trận Buôn Ma Thuột (10/3/1975)", "B. Trận Xuân Lộc (9/4/1975)", "C. Trận Pleiku (15/3/1975)", "D. Trận Phước Long (6/1/1975)"], "answer": "A. Trận Buôn Ma Thuột (10/3/1975)", "letter": "A"}, {"id": 61, "cat": "c2", "q": "Chiến dịch Hồ Chí Minh lịch sử giải phóng hoàn toàn miền Nam diễn ra trong khoảng thời gian nào?", "options": ["A. Từ ngày 18/3 đến 30/4/1975", "B. Từ ngày 1/4 đến 30/4/1975", "C. Từ ngày 26/4 đến 30/4/1975", "D. Từ ngày 10/3 đến 30/4/1975"], "answer": "C. Từ ngày 26/4 đến 30/4/1975", "letter": "C"}, {"id": 62, "cat": "c2", "q": "Thắng lợi ngày 30/4/1975 đã kết thúc bao nhiêu năm kháng chiến chống Mỹ, cứu nước và bao nhiêu năm chiến tranh giải phóng dân tộc (tính từ 1945)?", "options": ["A. 21 năm chống Mỹ và 30 năm chiến tranh giải phóng dân tộc", "B. 15 năm chống Mỹ và 25 năm chiến tranh giải phóng dân tộc", "C. 20 năm chống Mỹ và 35 năm chiến tranh giải phóng dân tộc", "D. 30 năm chống Mỹ và 45 năm chiến tranh giải phóng dân tộc"], "answer": "A. 21 năm chống Mỹ và 30 năm chiến tranh giải phóng dân tộc", "letter": "A"}, {"id": 63, "cat": "c3", "q": "Cuộc Tổng tuyển cử bầu Quốc hội chung của cả nước Việt Nam thống nhất diễn ra vào ngày tháng năm nào?", "options": ["A. Ngày 25/4/1976", "B. Ngày 21/11/1975", "C. Ngày 2/7/1976", "D. Ngày 14/12/1976"], "answer": "A. Ngày 25/4/1976", "letter": "A"}, {"id": 64, "cat": "c3", "q": "Tại kỳ họp đầu tiên (7/1976), bên cạnh việc quyết định đặt tên nước là Cộng hòa xã hội chủ nghĩa Việt Nam, Quốc hội khóa VI còn quyết định đổi tên thành phố nào?", "options": ["A. Đổi tên Đà Nẵng thành thành phố trực thuộc Trung ương", "B. Đổi tên Thăng Long thành Hà Nội", "C. Đổi tên Hải Phòng thành thành phố cảng Trung ương", "D. Đổi tên Sài Gòn – Gia Định thành Thành phố Hồ Chí Minh"], "answer": "D. Đổi tên Sài Gòn – Gia Định thành Thành phố Hồ Chí Minh", "letter": "D"}, {"id": 65, "cat": "c3", "q": "Đường lối công nghiệp hóa xã hội chủ nghĩa do Đại hội IV của Đảng (12/1976) đề ra có nội dung nào sau đây?", "options": ["A. Xóa bỏ toàn bộ công nghiệp nặng để tập trung 100% cho nông nghiệp", "B. Chỉ phát triển dịch vụ, du lịch và thương mại tư nhân", "C. Ưu tiên phát triển công nghiệp nặng một cách hợp lý, đồng thời ra sức phát triển nông nghiệp và công nghiệp nhẹ", "D. Chuyển ngay sang nền kinh tế thị trường mở cửa thu hút vốn FDI"], "answer": "C. Ưu tiên phát triển công nghiệp nặng một cách hợp lý, đồng thời ra sức phát triển nông nghiệp và công nghiệp nhẹ", "letter": "C"}, {"id": 66, "cat": "c3", "q": "Cuộc chiến tranh bảo vệ biên giới Tây Nam chống tập đoàn phản động Pôn Pốt diễn ra trong khoảng thời gian nào?", "options": ["A. Từ năm 1975 đến năm 1979", "B. Từ năm 1973 đến năm 1975", "C. Từ năm 1979 đến năm 1986", "D. Từ năm 1981 đến năm 1989"], "answer": "A. Từ năm 1975 đến năm 1979", "letter": "A"}, {"id": 67, "cat": "c3", "q": "Việt Nam thực hiện nghĩa vụ quốc tế cao cả, giúp lực lượng cách mạng và nhân dân Campuchia lật đổ chế độ diệt chủng Pôn Pốt vào thời gian nào?", "options": ["A. Tháng 1/1979", "B. Tháng 12/1976", "C. Tháng 4/1975", "D. Tháng 2/1982"], "answer": "A. Tháng 1/1979", "letter": "A"}, {"id": 68, "cat": "c1", "q": "Những nguyên nhân chính khiến nước ta lâm vào khủng hoảng kinh tế – xã hội nghiêm trọng vào cuối những năm 1970, đầu những năm 1980 là gì?", "options": ["A. Do thực hiện Khoán 10 quá nhanh trong nông nghiệp", "B. Do hậu quả nặng nề của chiến tranh, cơ chế quản lý tập trung quan liêu bao cấp kéo dài và sự bao vây, cấm vận của các thế lực thù địch", "C. Do nền kinh tế mở cửa quá sớm và cạnh tranh toàn cầu", "D. Do thiên tai liên tiếp và không có viện trợ từ bất kỳ nước nào"], "answer": "B. Do hậu quả nặng nề của chiến tranh, cơ chế quản lý tập trung quan liêu bao cấp kéo dài và sự bao vây, cấm vận của các thế lực thù địch", "letter": "B"}, {"id": 69, "cat": "c3", "q": "Chỉ thị số 100-CT/TW (1/1981) của Ban Bí thư — thường gọi là \"Khoán 100\" — quy định nội dung đột phá nào trong nông nghiệp?", "options": ["A. Giao quyền sử dụng đất vĩnh viễn cho doanh nghiệp nước ngoài", "B. Xóa bỏ hoàn toàn hợp tác xã nông nghiệp", "C. Tự do hóa hoàn toàn giá nông sản theo thị trường thế giới", "D. Khoán sản phẩm đến nhóm và người lao động trong hợp tác xã nông nghiệp"], "answer": "D. Khoán sản phẩm đến nhóm và người lao động trong hợp tác xã nông nghiệp", "letter": "D"}, {"id": 70, "cat": "c3", "q": "Các Quyết định 25-CP và 26-CP (1/1981) của Chính phủ nhằm giải quyết vấn đề gì trong lĩnh vực công nghiệp?", "options": ["A. Tư nhân hóa toàn bộ các nhà máy quốc doanh", "B. Cấm các địa phương tự tìm nguồn nguyên liệu sản xuất", "C. Mở rộng quyền tự chủ sản xuất, kinh doanh cho các xí nghiệp quốc doanh", "D. Sáp nhập tất cả xí nghiệp quốc doanh vào hợp tác xã thủ công nghiệp"], "answer": "C. Mở rộng quyền tự chủ sản xuất, kinh doanh cho các xí nghiệp quốc doanh", "letter": "C"}, {"id": 71, "cat": "c3", "q": "Hiện tượng nhiều địa phương, cơ sở sản xuất chủ động tìm cách tháo gỡ khó khăn vượt ra khỏi khuôn khổ cơ chế bao cấp cũ trong giai đoạn 1979–1985 được gọi là gì?", "options": ["A. \"Kinh tế tri thức\"", "B. \"Xé rào\"", "C. \"Bao cấp mở rộng\"", "D. \"Cải cách hành chính\""], "answer": "B. \"Xé rào\"", "letter": "B"}, {"id": 72, "cat": "c3", "q": "Hội nghị Trung ương 8 khóa V (6/1985) chủ trương xóa bỏ cơ chế tập trung quan liêu bao cấp thông qua bước đột phá nào?", "options": ["A. Ban hành Nghị quyết Khoán 10", "B. Ban hành Luật Đầu tư nước ngoài", "C. Thực hiện cải cách giá – lương – tiền", "D. Thành lập thị trường chứng khoán"], "answer": "C. Thực hiện cải cách giá – lương – tiền", "letter": "C"}, {"id": 73, "cat": "c3", "q": "Cuộc cải cách giá – lương – tiền (1985) có kết quả và ý nghĩa lịch sử như thế nào?", "options": ["A. Không thành công, gây ra những xáo trộn lớn về kinh tế – xã hội, nhưng để lại bài học sâu sắc thúc đẩy Đảng quyết tâm đổi mới toàn diện, triệt để hơn", "B. Chấm dứt hoàn toàn lạm phát xuống dưới 5%", "C. Thành công rực rỡ, đưa nước ta thoát ngay khỏi khủng hoảng năm 1985", "D. Đưa Việt Nam trở thành nước xuất khẩu gạo ngay trong năm 1985"], "answer": "A. Không thành công, gây ra những xáo trộn lớn về kinh tế – xã hội, nhưng để lại bài học sâu sắc thúc đẩy Đảng quyết tâm đổi mới toàn diện, triệt để hơn", "letter": "A"}, {"id": 74, "cat": "c3", "q": "Kết luận của Bộ Chính trị tháng 8/1986 tạo bước đột phá trực tiếp về mặt lý luận cho Đại hội VI khi tập trung làm rõ ba vấn đề lớn nào?", "options": ["A. Văn hóa, khoa học công nghệ và bảo vệ môi trường", "B. Quốc phòng, an ninh và đối ngoại đa phương", "C. Giáo dục, y tế và an sinh xã hội", "D. Cơ cấu sản xuất, cải tạo xã hội chủ nghĩa và cơ chế quản lý kinh tế"], "answer": "D. Cơ cấu sản xuất, cải tạo xã hội chủ nghĩa và cơ chế quản lý kinh tế", "letter": "D"}, {"id": 75, "cat": "c3", "q": "Tinh thần cốt lõi mở đầu công cuộc Đổi mới tại Đại hội đại biểu toàn quốc lần thứ VI (12/1986) là gì?", "options": ["A. Giữ nguyên cơ chế bao cấp nhưng tăng cường kỷ luật hành chính", "B. Nhìn thẳng vào sự thật, đánh giá đúng sự thật, khởi xướng đường lối đổi mới toàn diện, trước hết là đổi mới tư duy kinh tế", "C. Chỉ đổi mới chính trị mà không thay đổi cơ chế quản lý kinh tế", "D. Thay đổi mục tiêu chủ nghĩa xã hội sang kinh tế tư bản chủ nghĩa"], "answer": "B. Nhìn thẳng vào sự thật, đánh giá đúng sự thật, khởi xướng đường lối đổi mới toàn diện, trước hết là đổi mới tư duy kinh tế", "letter": "B"}, {"id": 76, "cat": "c3", "q": "Nghị quyết số 10-NQ/TW (4/1988) của Bộ Chính trị — còn gọi là \"Khoán 10\" — xác lập vai trò nào trong nông nghiệp?", "options": ["A. Hộ nông dân là đơn vị kinh tế tự chủ, được giao quyền sử dụng đất lâu dài", "B. Hợp tác xã giữ toàn quyền phân phối theo công điểm", "C. Nhà nước trực tiếp quản lý từng thửa ruộng của nông dân", "D. Chỉ cho phép trang trại quốc doanh sản xuất lương thực"], "answer": "A. Hộ nông dân là đơn vị kinh tế tự chủ, được giao quyền sử dụng đất lâu dài", "letter": "A"}, {"id": 77, "cat": "c3", "q": "Nhờ \"cú hích\" từ Nghị quyết 10 (Khoán 10, 4/1988), Việt Nam đã chuyển từ nước thiếu lương thực trở thành nước xuất khẩu gạo từ năm nào?", "options": ["A. Từ năm 1989", "B. Từ năm 1995", "C. Từ năm 1988", "D. Từ năm 1986"], "answer": "A. Từ năm 1989", "letter": "A"}, {"id": 78, "cat": "c3", "q": "Ngoài Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên CNXH (Cương lĩnh 1991), Đại hội VII (6/1991) còn thông qua văn kiện chiến lược nào?", "options": ["A. Chiến lược ổn định và phát triển kinh tế – xã hội đến năm 2000", "B. Chiến lược phát triển kinh tế biển đến năm 2030", "C. Chiến lược bảo vệ Tổ quốc trong tình hình mới", "D. Chiến lược phát triển kinh tế – xã hội 2011–2020"], "answer": "A. Chiến lược ổn định và phát triển kinh tế – xã hội đến năm 2000", "letter": "A"}, {"id": 79, "cat": "c3", "q": "Kết quả nổi bật nhất sau 10 năm đầu thực hiện công cuộc Đổi mới tính đến năm 1996 là gì?", "options": ["A. Đạt quy mô GDP trên 500 tỷ USD", "B. Đưa đất nước ra khỏi khủng hoảng kinh tế – xã hội kéo dài, tạo tiền đề chuyển sang thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa", "C. Chính thức gia nhập Tổ chức Thương mại Thế giới (WTO)", "D. Đưa Việt Nam trở thành nước công nghiệp hiện đại, thu nhập cao"], "answer": "B. Đưa đất nước ra khỏi khủng hoảng kinh tế – xã hội kéo dài, tạo tiền đề chuyển sang thời kỳ đẩy mạnh công nghiệp hóa, hiện đại hóa", "letter": "B"}, {"id": 80, "cat": "c3", "q": "Điểm chuyển biến trong đường lối đối ngoại tại Đại hội IX (4/2001) so với Đại hội VII (6/1991) là gì?", "options": ["A. Từ \"chỉ quan hệ với các nước XHCN\" sang \"mở cửa với ASEAN\"", "B. Chuyển từ \"hội nhập kinh tế\" sang \"tự cung tự cấp\"", "C. Chuyển từ \"đa phương hóa\" sang \"song phương hóa\"", "D. Chuyển từ \"muốn là bạn\" sang \"sẵn sàng là bạn, là đối tác tin cậy\" của các nước trong cộng đồng quốc tế"], "answer": "D. Chuyển từ \"muốn là bạn\" sang \"sẵn sàng là bạn, là đối tác tin cậy\" của các nước trong cộng đồng quốc tế", "letter": "D"}, {"id": 81, "cat": "c3", "q": "Việt Nam ký Nghị định thư gia nhập WTO vào ngày nào và chính thức có hiệu lực thành viên đầy đủ thứ 150 vào ngày nào?", "options": ["A. Ký ngày 7/11/2006, hiệu lực đầy đủ ngày 11/1/2007", "B. Ký ngày 1/1/2006, hiệu lực ngày 11/11/2006", "C. Ký ngày 11/11/2007, hiệu lực đầy đủ ngày 1/1/2008", "D. Ký ngày 25/4/2006, hiệu lực đầy đủ ngày 1/1/2007"], "answer": "A. Ký ngày 7/11/2006, hiệu lực đầy đủ ngày 11/1/2007", "letter": "A"}, {"id": 82, "cat": "c3", "q": "Đại hội XII (1/2016) của Đảng đã đẩy mạnh phong trào lớn nào gắn với công tác xây dựng, chỉnh đốn Đảng?", "options": ["A. Phong trào \"Bình dân học vụ\"", "B. Phong trào \"Khoán 100\"", "C. Phong trào học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh", "D. Phong trào \"Ba sẵn sàng\" và \"Ba đảm đang\""], "answer": "C. Phong trào học tập và làm theo tư tưởng, đạo đức, phong cách Hồ Chí Minh", "letter": "C"}, {"id": 83, "cat": "c3", "q": "Quan điểm nhất quán của Đảng trong công tác đấu tranh phòng, chống tham nhũng, tiêu cực, lãng phí là gì?", "options": ["A. \"Không có vùng cấm, không có ngoại lệ\"", "B. Chỉ xử lý khi gây thiệt hại trên mức quy định", "C. Xử lý nội bộ, ưu tiên nhắc nhở đối với cán bộ cấp cao", "D. Tạm hoãn xử lý để ưu tiên tăng trưởng kinh tế"], "answer": "A. \"Không có vùng cấm, không có ngoại lệ\"", "letter": "A"}, {"id": 84, "cat": "c3", "q": "Theo tài liệu Chương 3, hạn chế nổi bật còn tồn tại bên cạnh những thành tựu to lớn của công cuộc Đổi mới là gì?", "options": ["A. Quan hệ đối ngoại bị cô lập hoàn toàn với các nước lớn", "B. Chưa thiết lập được mô hình kinh tế nhiều thành phần", "C. Vẫn còn một bộ phận cán bộ, đảng viên suy thoái về tư tưởng chính trị, đạo đức, lối sống; tham nhũng, lãng phí, tiêu cực chưa bị ngăn chặn triệt để; nguy cơ tụt hậu kinh tế vẫn hiện hữu", "D. Việt Nam vẫn chưa thoát khỏi tình trạng thiếu lương thực"], "answer": "C. Vẫn còn một bộ phận cán bộ, đảng viên suy thoái về tư tưởng chính trị, đạo đức, lối sống; tham nhũng, lãng phí, tiêu cực chưa bị ngăn chặn triệt để; nguy cơ tụt hậu kinh tế vẫn hiện hữu", "letter": "C"}, {"id": 85, "cat": "c3", "q": "Theo bài học kinh nghiệm của công cuộc Đổi mới trong tài liệu Chương 3, mối quan hệ giữa đổi mới kinh tế và đổi mới chính trị được xử lý như thế nào?", "options": ["A. Tiến hành xóa bỏ toàn bộ hệ thống chính trị cũ trước khi cải cách kinh tế", "B. Đổi mới kinh tế đi trước một bước gắn với đổi mới từng bước về chính trị", "C. Chỉ đổi mới kinh tế, tuyệt đối không đổi mới chính trị", "D. Đổi mới chính trị trước rồi mới đổi mới kinh tế"], "answer": "B. Đổi mới kinh tế đi trước một bước gắn với đổi mới từng bước về chính trị", "letter": "B"}, {"id": 86, "cat": "dh13", "q": "Đại hội đại biểu toàn quốc lần thứ XIII của Đảng diễn ra trong thời gian nào và tại đâu?", "options": ["A. Từ ngày 20–28/1/2016 tại Hà Nội", "B. Từ ngày 12–19/1/2011 tại Hà Nội", "C. Từ ngày 19–23/1/2026 tại Hà Nội", "D. Từ ngày 25/1–1/2/2021 tại Hà Nội"], "answer": "D. Từ ngày 25/1–1/2/2021 tại Hà Nội", "letter": "D"}, {"id": 87, "cat": "dh13", "q": "Đại hội XIII của Đảng có bao nhiêu đại biểu tham dự, đại diện cho hơn 5 triệu đảng viên?", "options": ["A. 1.600 đại biểu", "B. 1.510 đại biểu", "C. 1.586 đại biểu", "D. 1.587 đại biểu"], "answer": "D. 1.587 đại biểu", "letter": "D"}, {"id": 88, "cat": "dh13", "q": "Cơ cấu nhân sự do Đại hội XIII của Đảng bầu ra gồm bao nhiêu Ủy viên Ban Chấp hành Trung ương và Ủy viên Bộ Chính trị?", "options": ["A. 220 Ủy viên BCH Trung ương (200 chính thức, 20 dự khuyết) và 18 Ủy viên Bộ Chính trị", "B. 180 Ủy viên BCH Trung ương (160 chính thức, 20 dự khuyết) và 16 Ủy viên Bộ Chính trị", "C. 200 Ủy viên BCH Trung ương (180 chính thức, 20 dự khuyết) và 18 Ủy viên Bộ Chính trị", "D. 200 Ủy viên BCH Trung ương (180 chính thức, 20 dự khuyết) và 19 Ủy viên Bộ Chính trị"], "answer": "C. 200 Ủy viên BCH Trung ương (180 chính thức, 20 dự khuyết) và 18 Ủy viên Bộ Chính trị", "letter": "C"}, {"id": 89, "cat": "dh13", "q": "Ai được bầu giữ chức Tổng Bí thư tại Đại hội đại biểu toàn quốc lần thứ XIII của Đảng (2021)?", "options": ["A. Đồng chí Phạm Minh Chính", "B. Đồng chí Tô Lâm", "C. Đồng chí Nguyễn Phú Trọng", "D. Đồng chí Nguyễn Xuân Phúc"], "answer": "C. Đồng chí Nguyễn Phú Trọng", "letter": "C"}, {"id": 90, "cat": "dh13", "q": "Phương châm của Đại hội đại biểu toàn quốc lần thứ XIII của Đảng là gì?", "options": ["A. \"Đoàn kết – Dân chủ – Kỷ cương – Sáng tạo – Phát triển\"", "B. \"Đoàn kết – Dân chủ – Kỷ cương – Đột phá – Phát triển\"", "C. \"Đoàn kết – Dân chủ – Kỷ cương – Đổi mới\"", "D. \"Đoàn kết – Kỷ cương – Hội nhập – Phát triển\""], "answer": "A. \"Đoàn kết – Dân chủ – Kỷ cương – Sáng tạo – Phát triển\"", "letter": "A"}, {"id": 91, "cat": "dh13", "q": "Bối cảnh thế giới nổi bật tác động mạnh mẽ khi diễn ra Đại hội XIII (1/2021) là gì?", "options": ["A. Kinh tế thế giới suy thoái nghiêm trọng do đại dịch Covid-19, cạnh tranh nước lớn gia tăng và Cách mạng công nghiệp lần thứ tư", "B. Khủng hoảng tài chính châu Á 1997 lan rộng", "C. Nền kinh tế toàn cầu tăng trưởng ổn định không có dịch bệnh", "D. Chiến tranh lạnh mới vừa kết thúc và Liên Xô vừa tan rã"], "answer": "A. Kinh tế thế giới suy thoái nghiêm trọng do đại dịch Covid-19, cạnh tranh nước lớn gia tăng và Cách mạng công nghiệp lần thứ tư", "letter": "A"}, {"id": 92, "cat": "dh13", "q": "\"Bốn nguy cơ\" mà Đảng đã chỉ ra và nhận định vẫn còn tồn tại tại Đại hội XIII là gì?", "options": ["A. Tụt hậu kinh tế, chệch hướng XHCN, tham nhũng – quan liêu, \"diễn biến hòa bình\"", "B. Xung đột biên giới, cấm vận kinh tế, chia rẽ khu vực, thiếu nhân lực", "C. Thiên tai, dịch bệnh, già hóa dân số, biến đổi khí hậu", "D. Lạm phát cao, thiếu lương thực, thất nghiệp, nợ công"], "answer": "A. Tụt hậu kinh tế, chệch hướng XHCN, tham nhũng – quan liêu, \"diễn biến hòa bình\"", "letter": "A"}, {"id": 93, "cat": "dh13", "q": "Chủ đề của Đại hội XIII xoay quanh mấy trụ cột lớn?", "options": ["A. 3 trụ cột", "B. 6 trụ cột", "C. 4 trụ cột", "D. 5 trụ cột"], "answer": "D. 5 trụ cột", "letter": "D"}, {"id": 94, "cat": "dh13", "q": "Theo báo cáo tại Đại hội XIII, tăng trưởng GDP bình quân giai đoạn nhiệm kỳ XII (2016–2020) và riêng năm 2020 đạt mức nào?", "options": ["A. Bình quân ~6,2%/năm; riêng năm 2020 đạt 8,02%", "B. Bình quân ~5%/năm; riêng năm 2020 tăng trưởng âm 1,5%", "C. Bình quân ~6%/năm; riêng năm 2020 đạt 2,91% — thuộc nhóm cao nhất thế giới giữa đại dịch", "D. Bình quân ~7%/năm; riêng năm 2020 đạt 5,0%"], "answer": "C. Bình quân ~6%/năm; riêng năm 2020 đạt 2,91% — thuộc nhóm cao nhất thế giới giữa đại dịch", "letter": "C"}, {"id": 95, "cat": "dh13", "q": "Theo thông tin Đại hội XIII, cuối nhiệm kỳ XII (2020), quy mô GDP và GDP bình quân đầu người của Việt Nam đạt bao nhiêu?", "options": ["A. GDP đạt 271,2 tỷ USD, bình quân đầu người 2.779 USD", "B. GDP đạt 400 tỷ USD, bình quân đầu người 4.100 USD", "C. GDP đạt 150 tỷ USD, bình quân đầu người 1.800 USD", "D. GDP đạt 514 tỷ USD, bình quân đầu người 5.026 USD"], "answer": "A. GDP đạt 271,2 tỷ USD, bình quân đầu người 2.779 USD", "letter": "A"}, {"id": 96, "cat": "dh13", "q": "Tốc độ tăng năng suất lao động của Việt Nam trong nhiệm kỳ XII (2016–2020) tăng từ mức nào (giai đoạn 2011–2015) lên mức nào?", "options": ["A. Từ 4,3%/năm lên 5,9%/năm", "B. Từ 3,0%/năm lên 4,5%/năm", "C. Từ 5,0%/năm lên 7,5%/năm", "D. Từ 2,9%/năm lên 6,2%/năm"], "answer": "A. Từ 4,3%/năm lên 5,9%/năm", "letter": "A"}, {"id": 97, "cat": "dh13", "q": "Trong kết quả nổi bật nhiệm kỳ Đại hội XII (2016–2020), chương trình xây dựng nông thôn mới đạt thành tích gì?", "options": ["A. Hoàn thành chậm 1 năm do ảnh hưởng của dịch bệnh", "B. Hoàn thành sớm gần 2 năm so với kế hoạch, làm thay đổi rõ nét bộ mặt nông thôn", "C. Mới chỉ triển khai thí điểm ở đồng bằng sông Hồng", "D. Hoàn thành đúng thời hạn 100% ở các tỉnh miền núi"], "answer": "B. Hoàn thành sớm gần 2 năm so với kế hoạch, làm thay đổi rõ nét bộ mặt nông thôn", "letter": "B"}, {"id": 98, "cat": "dh13", "q": "Theo thống kê tổng kết nhiệm kỳ XII tại Đại hội XIII, tỉ lệ hộ nghèo đa chiều và tỉ lệ bao phủ bảo hiểm y tế của nước ta đạt mức nào?", "options": ["A. Hộ nghèo đa chiều giảm còn dưới 5%; BHYT bao phủ trên 80% dân số", "B. Hộ nghèo đa chiều giảm còn 1,3%; BHYT bao phủ 95,2% dân số", "C. Hộ nghèo đa chiều giảm còn dưới 3%; BHYT bao phủ trên 90% dân số", "D. Hộ nghèo đa chiều giảm còn dưới 1%; BHYT bao phủ 100% dân số"], "answer": "C. Hộ nghèo đa chiều giảm còn dưới 3%; BHYT bao phủ trên 90% dân số", "letter": "C"}, {"id": 99, "cat": "dh13", "q": "Thành tựu nổi bật về giáo dục được nêu trong kết quả nhiệm kỳ XII tại Đại hội XIII là gì?", "options": ["A. Đưa 100% trường học chuyển sang học trực tuyến", "B. Phổ cập giáo dục mầm non cho trẻ 5 tuổi", "C. Phổ cập giáo dục trung học phổ thông toàn quốc", "D. Miễn học phí toàn bộ bậc đại học công lập"], "answer": "B. Phổ cập giáo dục mầm non cho trẻ 5 tuổi", "letter": "B"}, {"id": 100, "cat": "dh13", "q": "Mốc mục tiêu cụ thể đến năm 2025 (kỷ niệm 50 năm giải phóng hoàn toàn miền Nam, thống nhất đất nước) do Đại hội XIII đề ra là gì?", "options": ["A. Cơ bản hoàn thành giai đoạn tiền đề công nghiệp hóa", "B. Là nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao", "C. Là nước đang phát triển, có công nghiệp theo hướng hiện đại, vượt qua mức thu nhập trung bình thấp", "D. Trở thành nước phát triển, thu nhập cao"], "answer": "C. Là nước đang phát triển, có công nghiệp theo hướng hiện đại, vượt qua mức thu nhập trung bình thấp", "letter": "C"}, {"id": 101, "cat": "dh13", "q": "Mốc mục tiêu đến năm 2030 (kỷ niệm 100 năm thành lập Đảng) được Đại hội XIII xác định là gì?", "options": ["A. Là nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao", "B. Là nước đang phát triển, vượt qua mức thu nhập trung bình thấp", "C. Cơ bản xóa bỏ hoàn toàn nông nghiệp truyền thống", "D. Trở thành nước phát triển, thu nhập cao"], "answer": "A. Là nước đang phát triển, có công nghiệp hiện đại, thu nhập trung bình cao", "letter": "A"}, {"id": 102, "cat": "dh13", "q": "Mốc mục tiêu đến năm 2045 (kỷ niệm 100 năm thành lập nước) được Đại hội XIII xác định là gì?", "options": ["A. Nước đang phát triển có công nghiệp hiện đại", "B. Đạt thu nhập trung bình cao trong khu vực Đông Nam Á", "C. Trở thành nước phát triển, thu nhập cao", "D. Vượt qua mức thu nhập trung bình thấp"], "answer": "C. Trở thành nước phát triển, thu nhập cao", "letter": "C"}, {"id": 103, "cat": "dh13", "q": "Ba đột phá chiến lược được Đại hội XIII của Đảng xác định gồm những lĩnh vực nào?", "options": ["A. Cải cách tiền lương, xuất khẩu gạo và mở rộng khu công nghiệp", "B. Thể chế; Nguồn nhân lực & KHCN, đổi mới sáng tạo; Hạ tầng đồng bộ (ưu tiên giao thông, năng lượng, hạ tầng số)", "C. Giáo dục phổ thông, y tế dự phòng và du lịch sinh thái", "D. Nông nghiệp, công nghiệp nặng và thương mại quốc tế"], "answer": "B. Thể chế; Nguồn nhân lực & KHCN, đổi mới sáng tạo; Hạ tầng đồng bộ (ưu tiên giao thông, năng lượng, hạ tầng số)", "letter": "B"}, {"id": 104, "cat": "dh13", "q": "Trong đột phá về \"Hạ tầng đồng bộ\" của Đại hội XIII, những lĩnh vực nào được ưu tiên?", "options": ["A. Nhà ở thương mại và bất động sản nghỉ dưỡng", "B. Giao thông, năng lượng và hạ tầng số", "C. Du lịch, giải trí và bán lẻ", "D. Thủy lợi, lâm nghiệp và ngư nghiệp"], "answer": "B. Giao thông, năng lượng và hạ tầng số", "letter": "B"}, {"id": 105, "cat": "dh13", "q": "Đại hội XIII của Đảng đề ra bao nhiêu nhiệm vụ trọng tâm cho nhiệm kỳ mới?", "options": ["A. 4 nhiệm vụ trọng tâm", "B. 5 nhiệm vụ trọng tâm", "C. 6 nhiệm vụ trọng tâm", "D. 3 nhiệm vụ trọng tâm"], "answer": "C. 6 nhiệm vụ trọng tâm", "letter": "C"}, {"id": 106, "cat": "dh13", "q": "Nội dung \"Kiểm soát dịch bệnh, phục hồi và phát triển kinh tế – xã hội; đổi mới mô hình tăng trưởng; đẩy mạnh chuyển đổi số quốc gia\" thuộc phần nào của Đại hội XIII?", "options": ["A. Sáu nhiệm vụ trọng tâm nhiệm kỳ Đại hội XIII", "B. Bốn nguy cơ còn tồn tại", "C. Ba mốc mục tiêu chiến lược", "D. Kết quả nhiệm kỳ XII"], "answer": "A. Sáu nhiệm vụ trọng tâm nhiệm kỳ Đại hội XIII", "letter": "A"}, {"id": 107, "cat": "dh14", "q": "Đại hội đại biểu toàn quốc lần thứ XIV của Đảng diễn ra vào thời gian nào và tại đâu?", "options": ["A. Từ ngày 25/1–1/2/2021 tại Hà Nội", "B. Từ ngày 19–23/1/2026 tại Hà Nội", "C. Từ ngày 1–5/2/2026 tại Hà Nội", "D. Từ ngày 10–18/1/2026 tại TP. Hồ Chí Minh"], "answer": "B. Từ ngày 19–23/1/2026 tại Hà Nội", "letter": "B"}, {"id": 108, "cat": "dh14", "q": "Đại hội XIV của Đảng có bao nhiêu đại biểu tham dự và bầu ra bao nhiêu Ủy viên Bộ Chính trị?", "options": ["A. 1.586 đại biểu và 18 Ủy viên Bộ Chính trị", "B. 1.600 đại biểu và 20 Ủy viên Bộ Chính trị", "C. 1.586 đại biểu và 19 Ủy viên Bộ Chính trị", "D. 1.587 đại biểu và 18 Ủy viên Bộ Chính trị"], "answer": "C. 1.586 đại biểu và 19 Ủy viên Bộ Chính trị", "letter": "C"}, {"id": 109, "cat": "dh14", "q": "Ai được bầu giữ chức Tổng Bí thư Ban Chấp hành Trung ương Đảng khóa XIV (1/2026)?", "options": ["A. Đồng chí Nguyễn Phú Trọng", "B. Đồng chí Trần Thanh Mẫn", "C. Đồng chí Tô Lâm", "D. Đồng chí Phạm Minh Chính"], "answer": "C. Đồng chí Tô Lâm", "letter": "C"}, {"id": 110, "cat": "dh14", "q": "Số lượng Ủy viên Ban Chấp hành Trung ương khóa XIV được bầu tại Đại hội XIV là bao nhiêu?", "options": ["A. 200 Ủy viên (175 chính thức, 25 dự khuyết)", "B. 200 Ủy viên (180 chính thức, 20 dự khuyết)", "C. 180 Ủy viên (160 chính thức, 20 dự khuyết)", "D. 210 Ủy viên (190 chính thức, 20 dự khuyết)"], "answer": "B. 200 Ủy viên (180 chính thức, 20 dự khuyết)", "letter": "B"}, {"id": 111, "cat": "c1", "q": "Phương châm của Đại hội đại biểu toàn quốc lần thứ XIV của Đảng là gì?", "options": ["A. \"Đoàn kết – Tự cường – Đột phá – Hội nhập – Phát triển\"", "B. \"Đoàn kết – Dân chủ – Kỷ cương – Đổi mới\"", "C. \"Đoàn kết – Dân chủ – Kỷ cương – Sáng tạo – Phát triển\"", "D. \"Đoàn kết – Dân chủ – Kỷ cương – Đột phá – Phát triển\""], "answer": "D. \"Đoàn kết – Dân chủ – Kỷ cương – Đột phá – Phát triển\"", "letter": "D"}, {"id": 112, "cat": "dh14", "q": "So với phương châm Đại hội XIII, phương châm Đại hội XIV thay từ nào để nhấn mạnh yêu cầu hành động mạnh mẽ trong kỷ nguyên mới?", "options": ["A. Thay \"Phát triển\" bằng \"Thịnh vượng\"", "B. Thay \"Sáng tạo\" bằng \"Đột phá\"", "C. Thay \"Dân chủ\" bằng \"Tự chủ\"", "D. Thay \"Kỷ cương\" bằng \"Hội nhập\""], "answer": "B. Thay \"Sáng tạo\" bằng \"Đột phá\"", "letter": "B"}, {"id": 113, "cat": "dh14", "q": "Đại hội XIV được xác định là đại hội khởi đầu cho kỷ nguyên nào của dân tộc Việt Nam?", "options": ["A. Kỷ nguyên đổi mới và mở cửa", "B. Kỷ nguyên kinh tế nông nghiệp hiện đại", "C. Kỷ nguyên độc lập, thống nhất", "D. Kỷ nguyên phát triển mới của dân tộc — kỷ nguyên vươn mình"], "answer": "D. Kỷ nguyên phát triển mới của dân tộc — kỷ nguyên vươn mình", "letter": "D"}, {"id": 114, "cat": "dh14", "q": "Tại Đại hội XIV (sau 40 năm đổi mới), Đảng nhận định nguy cơ bao trùm đối với đất nước ta hiện nay là gì?", "options": ["A. Nguy cơ chưa được gia nhập các tổ chức kinh tế quốc tế", "B. Nguy cơ tụt hậu, nhất là về công nghệ, và rơi vào bẫy thu nhập trung bình", "C. Nguy cơ chiến tranh thế giới trực tiếp tại Đông Nam Á", "D. Nguy cơ thiếu lương thực và đói nghèo lan rộng"], "answer": "B. Nguy cơ tụt hậu, nhất là về công nghệ, và rơi vào bẫy thu nhập trung bình", "letter": "B"}, {"id": 115, "cat": "dh14", "q": "Trong bối cảnh thế giới tại Đại hội XIV, những công nghệ mũi nhọn nào của Cách mạng công nghiệp lần thứ tư được nhấn mạnh tạo biến đổi mang tính thời đại?", "options": ["A. Cơ khí hóa, điện khí hóa và tự động hóa dây chuyền cũ", "B. Năng lượng than đá và luyện kim truyền thống", "C. Trí tuệ nhân tạo, công nghệ số, công nghệ lượng tử", "D. Vận tải đường sắt hơi nước và điện báo"], "answer": "C. Trí tuệ nhân tạo, công nghệ số, công nghệ lượng tử", "letter": "C"}, {"id": 116, "cat": "dh14", "q": "Theo tổng kết nhiệm kỳ Đại hội XIII (2021–2026) tại Đại hội XIV, tăng trưởng GDP bình quân giai đoạn 2021–2025 và riêng năm 2025 đạt bao nhiêu?", "options": ["A. Bình quân ~6,2%/năm; riêng năm 2025 đạt 8,02%", "B. Bình quân ~5,5%/năm; riêng năm 2025 đạt 6,8%", "C. Bình quân ~6%/năm; riêng năm 2025 đạt 2,91%", "D. Bình quân ~8%/năm; riêng năm 2025 đạt 10,5%"], "answer": "A. Bình quân ~6,2%/năm; riêng năm 2025 đạt 8,02%", "letter": "A"}, {"id": 117, "cat": "dh14", "q": "Theo thông tin Đại hội XIV, quy mô GDP của Việt Nam cuối nhiệm kỳ XIII đạt mức nào và xếp thứ mấy trên thế giới?", "options": ["A. Vượt 800 tỷ USD, xếp thứ 20 thế giới", "B. Đạt 271,2 tỷ USD, xếp thứ 45 thế giới", "C. Đạt 350 tỷ USD, xếp thứ 40 thế giới", "D. Vượt 514 tỷ USD (gấp 1,48 lần năm 2020), xếp thứ 32 thế giới"], "answer": "D. Vượt 514 tỷ USD (gấp 1,48 lần năm 2020), xếp thứ 32 thế giới", "letter": "D"}, {"id": 118, "cat": "dh14", "q": "Theo báo cáo tại Đại hội XIV, GDP bình quân đầu người của Việt Nam cuối nhiệm kỳ XIII đạt bao nhiêu và đánh dấu cột mốc gì?", "options": ["A. 2.779 USD — vượt mức thu nhập thấp", "B. 3.800 USD — mức thu nhập trung bình thấp", "C. 5.026 USD — gia nhập nhóm thu nhập trung bình cao", "D. 8.500 USD — gia nhập nhóm thu nhập cao"], "answer": "C. 5.026 USD — gia nhập nhóm thu nhập trung bình cao", "letter": "C"}, {"id": 119, "cat": "dh14", "q": "Trong nhiệm kỳ Đại hội XIII (2021–2026), tỉ lệ hộ nghèo đa chiều và tỉ lệ bao phủ bảo hiểm y tế đạt kết quả nổi bật nào?", "options": ["A. Hộ nghèo đa chiều giảm từ 4,2% (2022) xuống 1,3% (2025); hoàn thành xóa nhà tạm, nhà dột nát cả nước; BHYT tăng lên 95,2% dân số", "B. Hộ nghèo đa chiều giảm còn 0%; BHYT đạt 100%", "C. Hộ nghèo đa chiều giảm từ 10% xuống 5%; BHYT đạt 85%", "D. Hộ nghèo đa chiều giảm dưới 3%; BHYT đạt trên 90%"], "answer": "A. Hộ nghèo đa chiều giảm từ 4,2% (2022) xuống 1,3% (2025); hoàn thành xóa nhà tạm, nhà dột nát cả nước; BHYT tăng lên 95,2% dân số", "letter": "A"}, {"id": 120, "cat": "dh14", "q": "Theo kết quả nhiệm kỳ XIII được nêu tại Đại hội XIV, Chỉ số phát triển con người (HDI) và Chỉ số hạnh phúc của Việt Nam biến chuyển như thế nào?", "options": ["A. HDI tăng 20 bậc đạt 0,850; chỉ số hạnh phúc xếp thứ 15/143 quốc gia", "B. HDI tăng 5 bậc đạt 0,700; chỉ số hạnh phúc tăng 10 bậc xếp thứ 70/143", "C. HDI giữ nguyên ở 0,680; chỉ số hạnh phúc tăng 12 bậc", "D. HDI tăng 14 bậc đạt 0,766 điểm; chỉ số hạnh phúc tăng 33 bậc, xếp thứ 46/143 quốc gia (2025)"], "answer": "D. HDI tăng 14 bậc đạt 0,766 điểm; chỉ số hạnh phúc tăng 33 bậc, xếp thứ 46/143 quốc gia (2025)", "letter": "D"}, {"id": 121, "cat": "dh14", "q": "Về phòng chống đại dịch Covid-19 trong nhiệm kỳ XIII, Đại hội XIV đánh giá Việt Nam đã thực hiện thành công điều gì?", "options": ["A. Chỉ tập trung chống dịch và tạm dừng toàn bộ hoạt động kinh tế", "B. Đóng cửa hoàn toàn biên giới trong suốt 5 năm", "C. Tự sản xuất 100% vắc-xin xuất khẩu ra toàn cầu từ năm 2021", "D. Ngoại giao vắc-xin, tiêm chủng miễn phí toàn quốc, thực hiện thành công \"mục tiêu kép\" — vừa chống dịch vừa phục hồi kinh tế"], "answer": "D. Ngoại giao vắc-xin, tiêm chủng miễn phí toàn quốc, thực hiện thành công \"mục tiêu kép\" — vừa chống dịch vừa phục hồi kinh tế", "letter": "D"}, {"id": 122, "cat": "dh14", "q": "Đại hội XIV đề ra mục tiêu tốc độ tăng trưởng GDP bình quân giai đoạn 2026–2030 và GDP bình quân đầu người đến năm 2030 đạt mức nào?", "options": ["A. GDP tăng 6–7%/năm; bình quân đầu người khoảng 6.000 USD", "B. GDP tăng từ 10%/năm trở lên; bình quân đầu người đạt khoảng 8.500 USD", "C. GDP tăng 8%/năm; bình quân đầu người khoảng 7.000 USD", "D. GDP tăng 12%/năm; bình quân đầu người khoảng 12.000 USD"], "answer": "B. GDP tăng từ 10%/năm trở lên; bình quân đầu người đạt khoảng 8.500 USD", "letter": "B"}, {"id": 123, "cat": "dh14", "q": "Hai mốc mục tiêu chiến lược 100 năm mà Đại hội XIV hướng tới thực hiện thành công là gì?", "options": ["A. 100 năm ngày sinh Chủ tịch Hồ Chí Minh và 100 năm Chiến thắng Điện Biên Phủ", "B. 100 năm gia nhập ASEAN và 100 năm gia nhập WTO", "C. 100 năm thống nhất đất nước (1975–2075) và 100 năm Đổi mới (1986–2086)", "D. 100 năm thành lập Đảng (1930–2030) và 100 năm thành lập nước (1945–2045)"], "answer": "D. 100 năm thành lập Đảng (1930–2030) và 100 năm thành lập nước (1945–2045)", "letter": "D"}, {"id": 124, "cat": "dh14", "q": "Trong Sáu nhiệm vụ trọng tâm của Đại hội XIV, thành phần kinh tế nào được khẳng định là \"động lực quan trọng nhất\"?", "options": ["A. Kinh tế hộ gia đình", "B. Kinh tế có vốn đầu tư nước ngoài", "C. Kinh tế tập thể", "D. Kinh tế tư nhân"], "answer": "D. Kinh tế tư nhân", "letter": "D"}, {"id": 125, "cat": "dh14", "q": "Trong nhiệm vụ cơ cấu lại nền kinh tế, đẩy mạnh CNH–HĐH tại Đại hội XIV, những yếu tố nào được xác định làm động lực chính?", "options": ["A. Tài nguyên thiên nhiên và lao động giá rẻ", "B. Xuất khẩu nguyên liệu thô và gia công giản đơn", "C. Khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số", "D. Vay vốn nước ngoài và mở rộng diện tích nông nghiệp"], "answer": "C. Khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số", "letter": "C"}, {"id": 126, "cat": "dh14", "q": "Trong nhiệm vụ xây dựng đồng bộ thể chế phát triển tại Đại hội XIV, yêu cầu cấp bách nào được nhấn mạnh để khơi thông mọi nguồn lực?", "options": ["A. Mở rộng quy mô bộ máy hành chính nhà nước", "B. Tháo gỡ kịp thời, dứt điểm các điểm nghẽn, nút thắt", "C. Giữ nguyên hệ thống thủ tục cũ để đảm bảo ổn định", "D. Hạn chế sự tham gia của khu vực tư nhân vào đầu tư hạ tầng"], "answer": "B. Tháo gỡ kịp thời, dứt điểm các điểm nghẽn, nút thắt", "letter": "B"}, {"id": 127, "cat": "dh14", "q": "Phương châm \"4 an\" bảo đảm cho Nhân dân trong nhiệm vụ phát triển nguồn lực con người, văn hóa tại Đại hội XIV là gì?", "options": ["A. An bình, an khang, an định, an toàn", "B. An sinh, an toàn, an nghiệp, an quốc", "C. An cư, an lạc, an tâm, an toàn", "D. An ninh, an sinh, an toàn, an dân"], "answer": "D. An ninh, an sinh, an toàn, an dân", "letter": "D"}, {"id": 128, "cat": "dh14", "q": "Nhiệm vụ quốc phòng – an ninh được Đại hội XIV xác định đối với Quân đội và Công an là xây dựng lực lượng theo định hướng nào?", "options": ["A. Tự vệ nhân dân kết hợp dân quân tại chỗ", "B. Bán chuyên nghiệp, linh hoạt, quy mô nhỏ", "C. Chuyên biệt về kinh tế và ngoại giao", "D. Cách mạng, chính quy, tinh nhuệ, hiện đại"], "answer": "D. Cách mạng, chính quy, tinh nhuệ, hiện đại", "letter": "D"}, {"id": 129, "cat": "dh14", "q": "Điểm mới nổi bật trong đột phá chiến lược về \"Kết cấu hạ tầng đồng bộ\" tại Đại hội XIV so với Đại hội XIII là nhấn mạnh bổ sung yếu tố nào?", "options": ["A. Hạ tầng nông nghiệp truyền thống", "B. Hạ tầng giao thông đa phương thức, hạ tầng công nghệ, chuyển đổi số, chuyển đổi xanh", "C. Hạ tầng kho bãi bao cấp", "D. Hạ tầng cảng cá ven biển đơn thuần"], "answer": "B. Hạ tầng giao thông đa phương thức, hạ tầng công nghệ, chuyển đổi số, chuyển đổi xanh", "letter": "B"}, {"id": 130, "cat": "dh14", "q": "Trong đột phá chiến lược về \"Nguồn nhân lực chất lượng cao\" tại Đại hội XIV, giải pháp nào được nhấn mạnh đặc biệt?", "options": ["A. Chuyển đổi cơ cấu, nâng cao chất lượng nguồn nhân lực trình độ cao; thu hút, trọng dụng nhân tài", "B. Chỉ sử dụng nguồn nhân lực từ khu vực doanh nghiệp nhà nước", "C. Giảm quy mô đào tạo đại học và sau đại học", "D. Chỉ đào tạo lao động phổ thông xuất khẩu"], "answer": "A. Chuyển đổi cơ cấu, nâng cao chất lượng nguồn nhân lực trình độ cao; thu hút, trọng dụng nhân tài", "letter": "A"}, {"id": 131, "cat": "dh14", "q": "Đặc trưng mục tiêu xây dựng đất nước trong mục tiêu tổng quát của Đại hội XIV hướng tới một nước Việt Nam xã hội chủ nghĩa như thế nào?", "options": ["A. Tự cấp, tự túc, ổn định lâu dài", "B. Dân giàu, nước mạnh, xã hội công bằng, văn minh", "C. Hòa bình, độc lập, dân chủ, giàu mạnh, phồn vinh, văn minh, hạnh phúc", "D. Độc lập, tự do, cơm áo, hòa bình"], "answer": "C. Hòa bình, độc lập, dân chủ, giàu mạnh, phồn vinh, văn minh, hạnh phúc", "letter": "C"}, {"id": 132, "cat": "dh14", "q": "Trong đột phá về \"Thể chế phát triển\" tại Đại hội XIV, nội dung cốt lõi cần nâng cao là gì?", "options": ["A. Tăng thêm số lượng văn bản quản lý hành chính trung gian", "B. Tái lập cơ chế kế hoạch hóa tập trung trong các ngành mũi nhọn", "C. Nâng cao năng lực hoạch định và tổ chức thực hiện chủ trương, đường lối của Đảng, chính sách, pháp luật của Nhà nước", "D. Thu hẹp quyền tự chủ của các địa phương và doanh nghiệp"], "answer": "C. Nâng cao năng lực hoạch định và tổ chức thực hiện chủ trương, đường lối của Đảng, chính sách, pháp luật của Nhà nước", "letter": "C"}, {"id": 133, "cat": "dh14", "q": "Điểm giống nhau trong cơ cấu Ban Chấp hành Trung ương khóa XIII và khóa XIV là gì?", "options": ["A. Đều gồm 200 Ủy viên BCH Trung ương (180 chính thức, 20 dự khuyết)", "B. Đều đặt mục tiêu tăng trưởng GDP bình quân từ 10%/năm trở lên", "C. Đều có 1.587 đại biểu tham dự Đại hội", "D. Đều có 18 Ủy viên Bộ Chính trị"], "answer": "A. Đều gồm 200 Ủy viên BCH Trung ương (180 chính thức, 20 dự khuyết)", "letter": "A"}, {"id": 134, "cat": "dh14", "q": "Điểm khác biệt về số lượng Ủy viên Bộ Chính trị giữa Đại hội XIII (2021) và Đại hội XIV (2026) là gì?", "options": ["A. Đại hội XIII bầu 18 Ủy viên, Đại hội XIV bầu 19 Ủy viên", "B. Đại hội XIII bầu 19 Ủy viên, Đại hội XIV bầu 18 Ủy viên", "C. Cả hai Đại hội đều bầu 19 Ủy viên Bộ Chính trị", "D. Đại hội XIII bầu 17 Ủy viên, Đại hội XIV bầu 20 Ủy viên"], "answer": "A. Đại hội XIII bầu 18 Ủy viên, Đại hội XIV bầu 19 Ủy viên", "letter": "A"}, {"id": 135, "cat": "dh14", "q": "Mốc thời gian kỷ niệm 40 năm công cuộc Đổi mới gắn liền với bối cảnh của Đại hội nào của Đảng?", "options": ["A. Đại hội XIV (2026)", "B. Đại hội XII (2016)", "C. Đại hội XIII (2021)", "D. Đại hội XI (2011)"], "answer": "A. Đại hội XIV (2026)", "letter": "A"}, {"id": 136, "cat": "dh14", "q": "Thách thức an ninh phi truyền thống nào được nhấn mạnh gia tăng nghiêm trọng trong bối cảnh thế giới tại Đại hội XIV?", "options": ["A. Biến đổi khí hậu, dịch bệnh ngày càng nghiêm trọng", "B. Chạy đua vũ trang hạt nhân thời Chiến tranh lạnh", "C. Khủng hoảng nợ công châu Âu năm 2010", "D. Xung đột biên giới lãnh thổ giữa các nước láng giềng"], "answer": "A. Biến đổi khí hậu, dịch bệnh ngày càng nghiêm trọng", "letter": "A"}, {"id": 137, "cat": "dh13", "q": "Trong kết quả nhiệm kỳ Đại hội XIII (2021–2026), lĩnh vực đối ngoại đã đạt thành tựu nổi bật nào?", "options": ["A. Lần đầu tiên gia nhập ASEAN và APEC", "B. Bình thường hóa quan hệ lần đầu tiên với Trung Quốc và Hoa Kỳ", "C. Nâng tầm quan hệ đối tác chiến lược toàn diện với các nước lớn, mở ra cục diện phát triển mới cho đất nước", "D. Ký Hiệp định Sơ bộ và Hiệp định Paris về chấm dứt chiến tranh"], "answer": "C. Nâng tầm quan hệ đối tác chiến lược toàn diện với các nước lớn, mở ra cục diện phát triển mới cho đất nước", "letter": "C"}, {"id": 138, "cat": "dh14", "q": "Điểm khác nhau về các mốc mục tiêu chiến lược được đặt ra tại Đại hội XIII và Đại hội XIV là gì?", "options": ["A. Đại hội XIII chỉ nêu mốc 2030; Đại hội XIV nêu mốc 2025 và 2050", "B. Cả hai Đại hội chỉ nêu duy nhất mốc năm 2045", "C. Đại hội XIII nêu 3 mốc (2025, 2030, 2045); Đại hội XIV tập trung vào 2 mốc chiến lược 100 năm (2030 và 2045)", "D. Đại hội XIII nêu mốc 2020 và 2030; Đại hội XIV nêu mốc 2035 và 2045"], "answer": "C. Đại hội XIII nêu 3 mốc (2025, 2030, 2045); Đại hội XIV tập trung vào 2 mốc chiến lược 100 năm (2030 và 2045)", "letter": "C"}, {"id": 139, "cat": "c1", "q": "Theo tài liệu Chương 1, sự kiện nào được xác định đã mở ra một thời đại mới, tác động sâu sắc đến phong trào yêu nước Việt Nam đầu thế kỷ XX?", "options": ["A. Cách mạng tư sản Pháp (1789) và Quốc tế thứ II", "B. Chiến tranh thế giới thứ hai (1939) và sự ra đời của Liên Hợp Quốc (1945)", "C. Cải cách Minh Trị ở Nhật Bản và phong trào Duy Tân ở Trung Quốc", "D. Thắng lợi của Cách mạng Tháng Mười Nga (1917) và sự ra đời của Quốc tế Cộng sản (1919)"], "answer": "D. Thắng lợi của Cách mạng Tháng Mười Nga (1917) và sự ra đời của Quốc tế Cộng sản (1919)", "letter": "D"}, {"id": 140, "cat": "c1", "q": "Tại sao sự ra đời của ba tổ chức cộng sản riêng lẻ năm 1929 đặt ra yêu cầu cấp bách phải hợp nhất thành một chính Đảng duy nhất?", "options": ["A. Vì Hội Việt Nam Cách mạng Thanh niên vẫn đủ sức lãnh đạo cả ba tổ chức", "B. Vì cả ba tổ chức đều theo khuynh hướng dân chủ tư sản", "C. Vì hoạt động riêng rẽ dẫn đến phân tán lực lượng và thiếu thống nhất về tổ chức trên cả nước", "D. Vì Quốc tế Cộng sản yêu cầu giải tán hoàn toàn phong trào công nhân"], "answer": "C. Vì hoạt động riêng rẽ dẫn đến phân tán lực lượng và thiếu thống nhất về tổ chức trên cả nước", "letter": "C"}, {"id": 141, "cat": "c1", "q": "Theo tài liệu Chương 1, các bài học kinh nghiệm của Cách mạng Tháng Tám năm 1945 gồm 4 nội dung chính nào?", "options": ["A. Đàm phán hòa bình; dựa vào viện trợ nước ngoài; đấu tranh nghị trường; mở cửa kinh tế thị trường", "B. Đánh nhanh thắng nhanh; tiêu thổ kháng chiến; cải cách ruộng đất triệt để; xây dựng công nghiệp nặng", "C. Chỉ đạo chiến lược đúng đắn; xây dựng lực lượng toàn dân (liên minh công–nông, mặt trận rộng rãi); nắm vững bạo lực cách mạng (chính trị kết hợp vũ trang, khởi nghĩa từng phần lên tổng khởi nghĩa); xây dựng Đảng cách mạng tiên phong", "D. Chuyển đổi số; thu hút nhân tài; đa phương hóa đối ngoại; xóa bỏ cơ chế bao cấp"], "answer": "C. Chỉ đạo chiến lược đúng đắn; xây dựng lực lượng toàn dân (liên minh công–nông, mặt trận rộng rãi); nắm vững bạo lực cách mạng (chính trị kết hợp vũ trang, khởi nghĩa từng phần lên tổng khởi nghĩa); xây dựng Đảng cách mạng tiên phong", "letter": "C"}, {"id": 142, "cat": "c1", "q": "Trong Cách mạng Tháng Tám năm 1945, nhân dân cả nước đã vùng dậy giành chính quyền thắng lợi trong khoảng thời gian bao lâu?", "options": ["A. Từ ngày 9/3 đến ngày 19/8/1945", "B. Từ ngày 19/8 đến ngày 2/9/1945", "C. Từ ngày 14/8 đến ngày 28/8/1945", "D. Từ ngày 13/8 đến ngày 23/8/1945"], "answer": "C. Từ ngày 14/8 đến ngày 28/8/1945", "letter": "C"}, {"id": 143, "cat": "c2", "q": "Theo tài liệu Chương 2, một trong những bài học kinh nghiệm quan trọng nhất của Đảng trong cuộc kháng chiến chống thực dân Pháp (1945–1954) về việc kết hợp nhiệm vụ là gì?", "options": ["A. Chỉ xây dựng lực lượng bộ đội chủ lực, không cần dân quân du kích", "B. Chỉ chống đế quốc, gác lại hoàn toàn nhiệm vụ xây dựng chế độ mới", "C. Tập trung toàn lực cho ngoại giao, hạn chế đấu tranh quân sự", "D. Kết hợp chặt chẽ hai nhiệm vụ cơ bản: vừa kháng chiến vừa kiến quốc, chống đế quốc và chống phong kiến"], "answer": "D. Kết hợp chặt chẽ hai nhiệm vụ cơ bản: vừa kháng chiến vừa kiến quốc, chống đế quốc và chống phong kiến", "letter": "D"}, {"id": 144, "cat": "c2", "q": "Theo tài liệu Chương 2, ý nghĩa của thắng lợi cuộc kháng chiến chống Pháp đối với dân tộc Việt Nam là gì?", "options": ["A. Hoàn thành cách mạng xã hội chủ nghĩa trên toàn lãnh thổ Việt Nam", "B. Giải phóng hoàn toàn cả hai miền Nam – Bắc ngay năm 1954", "C. Mở ra thời kỳ công nghiệp hóa, hiện đại hóa gắn với kinh tế tri thức", "D. Chấm dứt ách thống trị của thực dân Pháp trong gần một thế kỷ và giải phóng hoàn toàn miền Bắc"], "answer": "D. Chấm dứt ách thống trị của thực dân Pháp trong gần một thế kỷ và giải phóng hoàn toàn miền Bắc", "letter": "D"}, {"id": 145, "cat": "c2", "q": "Trong cuộc kháng chiến chống Mỹ, cứu nước (1954–1975), hậu phương lớn miền Bắc và tiền tuyến lớn miền Nam thực hiện nhiệm vụ chiến lược nào theo Đại hội III (9/1960)?", "options": ["A. Cả hai miền tạm dừng xây dựng kinh tế để chỉ đấu tranh ngoại giao", "B. Miền Bắc làm cách mạng dân tộc dân chủ, miền Nam làm cách mạng XHCN", "C. Cả hai miền cùng làm cách mạng xã hội chủ nghĩa ngay lập tức", "D. Cách mạng XHCN ở miền Bắc (vai trò quyết định nhất) và cách mạng dân tộc dân chủ nhân dân ở miền Nam (vai trò quyết định trực tiếp giải phóng miền Nam)"], "answer": "D. Cách mạng XHCN ở miền Bắc (vai trò quyết định nhất) và cách mạng dân tộc dân chủ nhân dân ở miền Nam (vai trò quyết định trực tiếp giải phóng miền Nam)", "letter": "D"}, {"id": 146, "cat": "c2", "q": "Theo tài liệu Chương 2, những bài học kinh nghiệm lớn của Đảng trong thời kỳ kháng chiến chống Mỹ (1954–1975) là gì?", "options": ["A. Thực hiện chiến lược \"đánh nhanh thắng nhanh\" ngay từ năm 1954", "B. Tạm gác mục tiêu thống nhất đất nước để ưu tiên hội nhập WTO", "C. Chỉ sử dụng đấu tranh chính trị hòa bình kết hợp ngoại giao quốc tế", "D. Giương cao ngọn cờ độc lập dân tộc và CNXH; phương pháp cách mạng tổng hợp (khởi nghĩa toàn dân và chiến tranh nhân dân); tổ chức chiến đấu giỏi, giành thắng lợi từng bước; coi trọng xây dựng Đảng, lực lượng và tranh thủ ủng hộ quốc tế"], "answer": "D. Giương cao ngọn cờ độc lập dân tộc và CNXH; phương pháp cách mạng tổng hợp (khởi nghĩa toàn dân và chiến tranh nhân dân); tổ chức chiến đấu giỏi, giành thắng lợi từng bước; coi trọng xây dựng Đảng, lực lượng và tranh thủ ủng hộ quốc tế", "letter": "D"}, {"id": 147, "cat": "c3", "q": "Theo tài liệu Chương 3, ý nghĩa của giai đoạn tìm tòi, thử nghiệm và cả những vấp váp trong các năm 1979–1986 là gì?", "options": ["A. Đưa Việt Nam gia nhập ngay tổ chức ASEAN vào năm 1986", "B. Chứng minh cơ chế bao cấp vẫn là mô hình tối ưu nhất", "C. Là quá trình chuẩn bị trực tiếp về mặt nhận thức và thực tiễn, tạo tiền đề quan trọng cho Đại hội VI (12/1986) đề ra đường lối đổi mới toàn diện đất nước", "D. Làm gián đoạn hoàn toàn quá trình thống nhất đất nước về mặt nhà nước"], "answer": "C. Là quá trình chuẩn bị trực tiếp về mặt nhận thức và thực tiễn, tạo tiền đề quan trọng cho Đại hội VI (12/1986) đề ra đường lối đổi mới toàn diện đất nước", "letter": "C"}, {"id": 148, "cat": "c3", "q": "Theo tài liệu Chương 3, Đại hội V (3/1982) của Đảng đã có nhận thức mới nào về thời kỳ quá độ lên chủ nghĩa xã hội ở nước ta?", "options": ["A. Cho phép đảng viên làm kinh tế tư nhân trên cả nước", "B. Xác định chặng đường đầu của thời kỳ quá độ phải trải qua nhiều chặng đường, điều chỉnh một số chỉ tiêu, nhiệm vụ kinh tế cho phù hợp thực tiễn", "C. Chính thức nêu khái niệm nền kinh tế thị trường định hướng XHCN", "D. Khẳng định hoàn thành sản xuất lớn XHCN ngay trong vòng 5 năm"], "answer": "B. Xác định chặng đường đầu của thời kỳ quá độ phải trải qua nhiều chặng đường, điều chỉnh một số chỉ tiêu, nhiệm vụ kinh tế cho phù hợp thực tiễn", "letter": "B"}, {"id": 149, "cat": "c3", "q": "Theo tài liệu Chương 3, trong công cuộc Đổi mới, Đảng xác định công tác xây dựng, chỉnh đốn Đảng giữ vị trí gì?", "options": ["A. Nhiệm vụ mang tính giai đoạn trước năm 2000", "B. Nhiệm vụ riêng của các cơ quan hành chính nhà nước", "C. Nhiệm vụ phụ trợ", "D. Nhiệm vụ then chốt"], "answer": "D. Nhiệm vụ then chốt", "letter": "D"}, {"id": 150, "cat": "c3", "q": "Theo tài liệu Chương 3, một trong 6 bài học kinh nghiệm lớn của công cuộc Đổi mới về mối quan hệ giữa sức mạnh dân tộc và quốc tế là gì?", "options": ["A. Kết hợp sức mạnh dân tộc với sức mạnh thời đại, chủ động và tích cực hội nhập quốc tế toàn diện, sâu rộng", "B. Chỉ hội nhập kinh tế mà không phát triển quan hệ đối ngoại đa phương", "C. Đóng cửa tự lực tuyệt đối để tránh ảnh hưởng bên ngoài", "D. Phụ thuộc hoàn toàn vào vốn đầu tư trực tiếp nước ngoài"], "answer": "A. Kết hợp sức mạnh dân tộc với sức mạnh thời đại, chủ động và tích cực hội nhập quốc tế toàn diện, sâu rộng", "letter": "A"}, {"id": 151, "cat": "dh14", "q": "Tại Đại hội XIV (2026), tinh thần hành động mới được xác định trong mục tiêu tổng quát để tiến mạnh vào kỷ nguyên mới của dân tộc gồm những yếu tố nào?", "options": ["A. Thụ động, chờ thời, thận trọng", "B. Bao cấp, tập trung, khép kín", "C. Tự chủ chiến lược, tự cường, tự tin, tiến mạnh vào kỷ nguyên mới của dân tộc", "D. Tạm dừng công nghiệp hóa để ổn định lạm phát"], "answer": "C. Tự chủ chiến lược, tự cường, tự tin, tiến mạnh vào kỷ nguyên mới của dân tộc", "letter": "C"}, {"id": 152, "cat": "dh14", "q": "So với mức tăng trưởng GDP bình quân nhiệm kỳ XII (~6%/năm) và nhiệm kỳ XIII (~6,2%/năm), mục tiêu tăng trưởng GDP bình quân giai đoạn 2026–2030 do Đại hội XIV đề ra có bước nhảy vọt như thế nào?", "options": ["A. Tăng nhẹ lên 7%/năm", "B. Tăng tốc lên từ 10%/năm trở lên", "C. Giữ ổn định ở mức 6,5%/năm", "D. Giảm xuống 5%/năm để ưu tiên môi trường"], "answer": "B. Tăng tốc lên từ 10%/năm trở lên", "letter": "B"}, {"id": 153, "cat": "dh14", "q": "Trong nhiệm kỳ XIII (2021–2026), chỉ số nào phản ánh mức độ cải thiện mạnh mẽ chất lượng cuộc sống và sự hài lòng của người dân Việt Nam trên bảng xếp hạng toàn cầu năm 2025?", "options": ["A. Chỉ số xuất khẩu nông sản đứng thứ 1 toàn cầu", "B. Tỉ lệ đô thị hóa đạt 100% cả nước", "C. Chỉ số hạnh phúc tăng 33 bậc, xếp thứ 46/143 quốc gia", "D. Tuổi thọ trung bình đạt 95 tuổi"], "answer": "C. Chỉ số hạnh phúc tăng 33 bậc, xếp thứ 46/143 quốc gia", "letter": "C"}, {"id": 154, "cat": "dh14", "q": "Đại hội XIV (1/2026) khẳng định thành tựu xóa bỏ loại hình nhà ở nào trên phạm vi cả nước trong nhiệm kỳ Đại hội XIII?", "options": ["A. Nhà chung cư cũ ở các đô thị lớn", "B. Hoàn thành xóa nhà tạm, nhà dột nát cả nước", "C. Toàn bộ nhà trọ sinh viên", "D. Nhà ở ven sông ở Đồng bằng sông Cửu Long"], "answer": "B. Hoàn thành xóa nhà tạm, nhà dột nát cả nước", "letter": "B"}, {"id": 155, "cat": "c1", "q": "Theo tài liệu tóm tắt Chương 1, phong trào yêu nước theo khuynh hướng phong kiến tiêu biểu ở Việt Nam cuối thế kỷ XIX là phong trào nào?", "options": ["A. Phong trào Cần Vương", "B. Khởi nghĩa Yên Bái", "C. Phong trào Đông Du", "D. Phong trào Duy Tân"], "answer": "A. Phong trào Cần Vương", "letter": "A"}, {"id": 156, "cat": "c1", "q": "Theo tài liệu Chương 1, năm 1920 Nguyễn Ái Quốc đọc Sơ thảo lần thứ nhất những luận cương về vấn đề dân tộc và vấn đề thuộc địa của V.I. Lênin và tìm thấy con đường cứu nước đúng đắn nào?", "options": ["A. Con đường bạo động phong kiến", "B. Con đường quân chủ lập hiến", "C. Con đường cách mạng vô sản", "D. Con đường cải cách dân chủ tư sản"], "answer": "C. Con đường cách mạng vô sản", "letter": "C"}, {"id": 157, "cat": "c1", "q": "Trong Cương lĩnh chính trị đầu tiên (2/1930), mối quan hệ giữa cách mạng Việt Nam và cách mạng thế giới được xác định như thế nào?", "options": ["A. Cách mạng Việt Nam là một bộ phận của cách mạng vô sản thế giới", "B. Cách mạng Việt Nam hoàn toàn tách biệt với cách mạng thế giới", "C. Cách mạng Việt Nam chỉ liên minh với các nước thuộc địa ở châu Phi", "D. Cách mạng Việt Nam phụ thuộc vào cách mạng tư sản phương Tây"], "answer": "A. Cách mạng Việt Nam là một bộ phận của cách mạng vô sản thế giới", "letter": "A"}, {"id": 158, "cat": "c1", "q": "Theo tài liệu Chương 1, Luận cương chính trị tháng 10/1930 xác định tính chất và hướng phát triển của cách mạng Đông Dương như thế nào?", "options": ["A. Cách mạng tư sản dân quyền, phát triển bỏ qua thời kỳ tư bản chủ nghĩa tiến thẳng lên chủ nghĩa xã hội", "B. Cách mạng giải phóng dân tộc tạm gác toàn bộ vấn đề giai cấp", "C. Cải cách hòa bình trong khuôn khổ chế độ thực dân Pháp", "D. Cách mạng dân chủ tư sản kiểu cũ tiến lên chủ nghĩa tư bản"], "answer": "A. Cách mạng tư sản dân quyền, phát triển bỏ qua thời kỳ tư bản chủ nghĩa tiến thẳng lên chủ nghĩa xã hội", "letter": "A"}, {"id": 159, "cat": "c1", "q": "Trước sự khủng bố trắng ác liệt của thực dân Pháp sau cao trào Xô viết Nghệ – Tĩnh (1930–1931), Đảng Cộng sản Đông Dương đã có hành động gì?", "options": ["A. Giải tán hoàn toàn tổ chức Đảng trên cả nước", "B. Chuyển sang khuynh hướng dân chủ tư sản", "C. Rút vào bí mật, kiên cường giữ vững ý chí và từng bước khôi phục hệ thống tổ chức", "D. Ký hòa ước thỏa hiệp với chính quyền thực dân Pháp"], "answer": "C. Rút vào bí mật, kiên cường giữ vững ý chí và từng bước khôi phục hệ thống tổ chức", "letter": "C"}, {"id": 160, "cat": "c1", "q": "Trong phong trào dân chủ 1936–1939, Đảng Cộng sản Đông Dương đã kết hợp những hình thức đấu tranh nào?", "options": ["A. Chỉ đấu tranh nghị trường, bỏ hẳn hoạt động bí mật", "B. Chỉ đấu tranh vũ trang bí mật trong rừng núi", "C. Kết hợp đấu tranh công khai, hợp pháp với bí mật, bất hợp pháp", "D. Chỉ bãi công kinh tế, không tham gia báo chí"], "answer": "C. Kết hợp đấu tranh công khai, hợp pháp với bí mật, bất hợp pháp", "letter": "C"}, {"id": 161, "cat": "c1", "q": "Phong trào quần chúng sôi nổi mở đầu thời kỳ dân chủ 1936–1939 nhằm thu thập nguyện vọng gửi tới phái đoàn Quốc hội Pháp là phong trào nào?", "options": ["A. Phong trào Xô viết Nghệ – Tĩnh", "B. Phong trào Đông Du", "C. Phong trào Đồng khởi", "D. Phong trào Đông Dương Đại hội"], "answer": "D. Phong trào Đông Dương Đại hội", "letter": "D"}, {"id": 162, "cat": "c1", "q": "Tháng 8/1945, sự kiện quốc tế nào tạo ra thời cơ \"ngàn năm có một\" cho nhân dân Việt Nam Tổng khởi nghĩa giành chính quyền?", "options": ["A. Đức tấn công Ba Lan mở màn Chiến tranh thế giới thứ hai", "B. Phát xít Nhật tiến vào Đông Dương", "C. Phát xít Nhật đầu hàng Đồng minh", "D. Chính phủ Mặt trận nhân dân Pháp lên cầm quyền"], "answer": "C. Phát xít Nhật đầu hàng Đồng minh", "letter": "C"}, {"id": 163, "cat": "c1", "q": "Theo tài liệu Chương 1, Cách mạng Tháng Tám 1945 đã lập nên nhà nước đầu tiên kiểu nào ở khu vực Đông Nam Á?", "options": ["A. Nhà nước của nhân dân (dân chủ nhân dân) đầu tiên ở Đông Nam Á", "B. Nhà nước liên bang tư sản đầu tiên ở Đông Nam Á", "C. Nhà nước quân chủ lập hiến đầu tiên ở Đông Nam Á", "D. Nhà nước tự trị thuộc khối Liên hiệp Pháp"], "answer": "A. Nhà nước của nhân dân (dân chủ nhân dân) đầu tiên ở Đông Nam Á", "letter": "A"}, {"id": 164, "cat": "c1", "q": "Trong tình thế \"ngàn cân treo sợi tóc\" ngay sau Cách mạng Tháng Tám 1945, quân Pháp đã núp bóng lực lượng nào để quay trở lại gây hấn ở miền Nam ngày 23/9/1945?", "options": ["A. Quân đội Anh", "B. Quân đội Trung Hoa Dân quốc", "C. Quân đội Mỹ", "D. Quân đội Nhật"], "answer": "A. Quân đội Anh", "letter": "A"}, {"id": 165, "cat": "c2", "q": "Để xây dựng lại Ngân khố quốc gia và từng bước chuẩn bị cho việc phát hành đồng giấy bạc Việt Nam ngay sau Cách mạng Tháng Tám 1945, Chính phủ đã dựa vào biện pháp nào?", "options": ["A. Vay viện trợ không hoàn lại từ các nước Đồng minh phương Tây", "B. Tăng gấp đôi thuế thân và thuế ruộng đất thời Pháp thuộc", "C. Thành lập \"Quỹ Độc lập\" và tổ chức \"Tuần lễ vàng\" quyên góp vàng, tài chính từ nhân dân", "D. Bán toàn bộ hầm mỏ và đồn điền cho nước ngoài"], "answer": "C. Thành lập \"Quỹ Độc lập\" và tổ chức \"Tuần lễ vàng\" quyên góp vàng, tài chính từ nhân dân", "letter": "C"}, {"id": 166, "cat": "c2", "q": "Nhờ phong trào tăng gia sản xuất và thực hành tiết kiệm (\"Hũ gạo tiết kiệm\", \"Ngày đồng tâm\"), nạn đói sau Cách mạng Tháng Tám 1945 cơ bản được đẩy lùi vào thời điểm nào?", "options": ["A. Đến năm 1950", "B. Đến cuối năm 1947", "C. Đến đầu năm 1946", "D. Ngay trong tháng 9/1945"], "answer": "C. Đến đầu năm 1946", "letter": "C"}, {"id": 167, "cat": "c2", "q": "Trong cuộc kháng chiến chống Pháp (1951–1954), để bồi dưỡng sức dân và củng cố hậu phương kháng chiến toàn diện, Đảng đã thực hiện chủ trương gì ở nông thôn?", "options": ["A. Thành lập các khu chế xuất và khu công nghiệp hiện đại", "B. Chỉnh đốn Đảng, phát triển kinh tế, văn hóa và từng bước cải cách ruộng đất", "C. Áp dụng Khoán 10 giao đất lâu dài cho hộ nông dân", "D. Xóa bỏ hoàn toàn sản xuất nông nghiệp để chuyển sang công nghiệp nặng"], "answer": "B. Chỉnh đốn Đảng, phát triển kinh tế, văn hóa và từng bước cải cách ruộng đất", "letter": "B"}, {"id": 168, "cat": "c2", "q": "Chiến thắng Điện Biên Phủ (7/5/1954) được tài liệu Chương 2 đánh giá bằng cụm từ nổi tiếng nào?", "options": ["A. \"Kỷ nguyên vươn mình của dân tộc\"", "B. \"Lừng lẫy năm châu, chấn động địa cầu\"", "C. \"Cuộc tổng diễn tập đầu tiên của cách mạng Việt Nam\"", "D. \"Đòn thăm dò chiến lược quyết định\""], "answer": "B. \"Lừng lẫy năm châu, chấn động địa cầu\"", "letter": "B"}, {"id": 169, "cat": "c2", "q": "Theo tài liệu Chương 2, thắng lợi cuộc kháng chiến chống thực dân Pháp còn gắn liền với sự ủng hộ quốc tế nào?", "options": ["A. Sự hỗ trợ của chính quyền thực dân Anh tại Đông Nam Á", "B. Sự giúp đỡ của Liên Xô, Trung Quốc, các nước XHCN anh em và nhân dân yêu chuộng hòa bình trên thế giới, kể cả nhân dân tiến bộ Pháp", "C. Sự tài trợ tài chính từ Quỹ Tiền tệ Quốc tế (IMF)", "D. Sự viện trợ quân sự trực tiếp của Hoa Kỳ và khối NATO"], "answer": "B. Sự giúp đỡ của Liên Xô, Trung Quốc, các nước XHCN anh em và nhân dân yêu chuộng hòa bình trên thế giới, kể cả nhân dân tiến bộ Pháp", "letter": "B"}, {"id": 170, "cat": "c2", "q": "Sau năm 1954, chế độ chính trị – xã hội của miền Nam Việt Nam mang đặc điểm nào theo tài liệu Chương 2?", "options": ["A. Được giải phóng hoàn toàn và tiến lên chủ nghĩa xã hội", "B. Là khu vực trung lập dưới sự quản lý của Liên Hợp Quốc", "C. Trở thành thuộc địa kiểu mới của đế quốc Mỹ", "D. Vẫn là thuộc địa kiểu cũ do thực dân Pháp trực tiếp cai trị"], "answer": "C. Trở thành thuộc địa kiểu mới của đế quốc Mỹ", "letter": "C"}, {"id": 171, "cat": "c2", "q": "Đại hội III của Đảng (9/1960) đã thông qua kế hoạch phát triển kinh tế nào ở miền Bắc nhằm bước đầu xây dựng cơ sở vật chất – kỹ thuật của chủ nghĩa xã hội?", "options": ["A. Kế hoạch 5 năm lần thứ hai (1976–1980)", "B. Kế hoạch 3 năm (1955–1957)", "C. Kế hoạch 5 năm lần thứ nhất (1961–1965)", "D. Chiến lược ổn định kinh tế – xã hội đến năm 2000"], "answer": "C. Kế hoạch 5 năm lần thứ nhất (1961–1965)", "letter": "C"}, {"id": 172, "cat": "c2", "q": "Năm 1965, khi đứng trước nguy cơ phá sản của chiến lược \"Chiến tranh đặc biệt\", đế quốc Mỹ đã chuyển sang hành động leo thang nào?", "options": ["A. Rút toàn bộ quân đội và cố vấn khỏi miền Nam Việt Nam", "B. Ồ ạt đưa quân viễn chinh vào miền Nam tiến hành \"Chiến tranh cục bộ\" đồng thời leo thang chiến tranh phá hoại miền Bắc lần thứ nhất", "C. Trao trả lại miền Nam cho thực dân Pháp quản lý", "D. Ký Hiệp định Paris chấm dứt chiến tranh ngay lập tức"], "answer": "B. Ồ ạt đưa quân viễn chinh vào miền Nam tiến hành \"Chiến tranh cục bộ\" đồng thời leo thang chiến tranh phá hoại miền Bắc lần thứ nhất", "letter": "B"}, {"id": 173, "cat": "c2", "q": "Việc thành lập Chính phủ Cách mạng lâm thời Cộng hòa miền Nam Việt Nam (6/1969) có ý nghĩa quan trọng nhất đối với mặt trận nào?", "options": ["A. Mở đường cho chiến lược \"Chiến tranh đơn phương\"", "B. Giải phóng hoàn toàn các đô thị miền Nam ngay trong năm 1969", "C. Đáp ứng yêu cầu phát triển của cách mạng, nhất là trong đấu tranh ngoại giao", "D. Thay thế hoàn toàn vai trò của Quốc hội nước Việt Nam Dân chủ Cộng hòa"], "answer": "C. Đáp ứng yêu cầu phát triển của cách mạng, nhất là trong đấu tranh ngoại giao", "letter": "C"}, {"id": 174, "cat": "c2", "q": "Theo tài liệu Chương 2, thắng lợi của cuộc kháng chiến chống Mỹ, cứu nước (1954–1975) có ý nghĩa quốc tế gì?", "options": ["A. Là một trong những chiến công vĩ đại của dân tộc trong thế kỷ XX, cổ vũ mạnh mẽ phong trào giải phóng dân tộc, dân chủ và hòa bình trên thế giới", "B. Làm tan rã khối ASEAN vào năm 1975", "C. Mở đầu Chiến tranh thế giới thứ ba", "D. Chấm dứt hoàn toàn sự tồn tại của Liên Hợp Quốc"], "answer": "A. Là một trong những chiến công vĩ đại của dân tộc trong thế kỷ XX, cổ vũ mạnh mẽ phong trào giải phóng dân tộc, dân chủ và hòa bình trên thế giới", "letter": "A"}, {"id": 175, "cat": "c3", "q": "Đại hội XI của Đảng (1/2011) thông qua Chiến lược phát triển kinh tế – xã hội 2011–2020 với định hướng gắn công nghiệp hóa, hiện đại hóa với yếu tố nào?", "options": ["A. Sản xuất nông nghiệp tự cung tự cấp", "B. Phát triển kinh tế tri thức", "C. Cơ chế bao cấp tập trung", "D. Khai thác tối đa tài nguyên thô"], "answer": "B. Phát triển kinh tế tri thức", "letter": "B"}, {"id": 176, "cat": "c3", "q": "Theo tài liệu Chương 3, một trong các bài học kinh nghiệm của công cuộc Đổi mới về việc xử lý mâu thuẫn mới phát sinh trong thực tiễn là gì?", "options": ["A. Tạm dừng công cuộc đổi mới khi xuất hiện khó khăn kinh tế", "B. Giao toàn bộ công tác giải quyết mâu thuẫn cho các tổ chức quốc tế", "C. Chủ động dự báo, kịp thời phát hiện và giải quyết những mâu thuẫn, vấn đề mới sinh; kiên quyết, kiên trì đấu tranh phòng, chống tham nhũng, tiêu cực gắn với xây dựng, chỉnh đốn Đảng", "D. Chờ đợi vấn đề tự lắng xuống rồi mới xử lý hành chính"], "answer": "C. Chủ động dự báo, kịp thời phát hiện và giải quyết những mâu thuẫn, vấn đề mới sinh; kiên quyết, kiên trì đấu tranh phòng, chống tham nhũng, tiêu cực gắn với xây dựng, chỉnh đốn Đảng", "letter": "C"}, {"id": 177, "cat": "dh13", "q": "Theo tài liệu Đại hội XIII, 5 trụ cột của Chủ đề Đại hội XIII KHÔNG bao gồm nội dung nào sau đây?", "options": ["A. Tái lập cơ chế kế hoạch hóa tập trung bao cấp trong các ngành kinh tế trọng điểm", "B. Khơi dậy ý chí, khát vọng phát triển đất nước gắn với sức mạnh đại đoàn kết dân tộc và sức mạnh thời đại", "C. Tăng cường xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh", "D. Đẩy mạnh toàn diện, đồng bộ công cuộc đổi mới; xây dựng, bảo vệ vững chắc Tổ quốc; phấn đấu giữa thế kỷ XXI trở thành nước phát triển định hướng XHCN"], "answer": "A. Tái lập cơ chế kế hoạch hóa tập trung bao cấp trong các ngành kinh tế trọng điểm", "letter": "A"}, {"id": 178, "cat": "dh13", "q": "Trong Sáu nhiệm vụ trọng tâm của Đại hội XIII, nhiệm vụ số 1 được đặt lên hàng đầu là gì?", "options": ["A. Kiểm soát dịch bệnh và chuyển đổi số", "B. Quản lý chặt chẽ đất đai, tài nguyên và thích ứng biến đổi khí hậu", "C. Xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh toàn diện; đẩy mạnh đấu tranh phòng, chống tham nhũng, lãng phí, tiêu cực", "D. Hoàn thiện hệ thống giao thông đường bộ cao tốc"], "answer": "C. Xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh toàn diện; đẩy mạnh đấu tranh phòng, chống tham nhũng, lãng phí, tiêu cực", "letter": "C"}, {"id": 179, "cat": "dh14", "q": "Trong Sáu nhiệm vụ trọng tâm của Đại hội XIII, nhiệm vụ về văn hóa và xã hội nhấn mạnh nội dung nào?", "options": ["A. Phổ cập đại học cho 100% dân số vào năm 2025", "B. Chuyển toàn bộ y tế công lập sang tư nhân hóa", "C. Khơi dậy khát vọng phát triển đất nước phồn vinh, hạnh phúc; phát huy giá trị văn hóa, con người Việt Nam; bảo đảm an sinh xã hội", "D. Xóa bỏ hoàn toàn các loại hình văn hóa truyền thống địa phương"], "answer": "C. Khơi dậy khát vọng phát triển đất nước phồn vinh, hạnh phúc; phát huy giá trị văn hóa, con người Việt Nam; bảo đảm an sinh xã hội", "letter": "C"}, {"id": 180, "cat": "dh13", "q": "Trong Sáu nhiệm vụ trọng tâm của Đại hội XIII, nhiệm vụ về tài nguyên và môi trường đề ra yêu cầu gì?", "options": ["A. Chuyển toàn bộ đất nông nghiệp sang đất công nghiệp", "B. Khai thác triệt để tài nguyên khoáng sản để tăng trưởng ngắn hạn", "C. Dừng toàn bộ các dự án năng lượng tái tạo", "D. Quản lý chặt chẽ, hiệu quả đất đai, tài nguyên; bảo vệ môi trường; chủ động thích ứng với biến đổi khí hậu"], "answer": "D. Quản lý chặt chẽ, hiệu quả đất đai, tài nguyên; bảo vệ môi trường; chủ động thích ứng với biến đổi khí hậu", "letter": "D"}, {"id": 181, "cat": "dh13", "q": "Trong Sáu nhiệm vụ trọng tâm của Đại hội XIII, nhiệm vụ về pháp luật và dân chủ nêu rõ điều gì?", "options": ["A. Chỉ tập trung sửa đổi luật thuế xuất nhập khẩu", "B. Hoàn thiện pháp luật, phát huy dân chủ xã hội chủ nghĩa, quyền làm chủ của nhân dân; tăng cường đại đoàn kết toàn dân tộc", "C. Thu hẹp quyền giám sát của Mặt trận Tổ quốc", "D. Áp dụng nguyên xi hệ thống pháp luật phương Tây"], "answer": "B. Hoàn thiện pháp luật, phát huy dân chủ xã hội chủ nghĩa, quyền làm chủ của nhân dân; tăng cường đại đoàn kết toàn dân tộc", "letter": "B"}, {"id": 182, "cat": "dh13", "q": "Trong Ba đột phá chiến lược của Đại hội XIII, đột phá về \"Thể chế\" xác định hoàn thiện thể chế kinh tế thị trường định hướng XHCN theo 4 tính chất nào?", "options": ["A. Nhanh chóng, linh hoạt, khép kín, tự cấp", "B. Tập trung, bao cấp, ổn định, dài hạn", "C. Tự phát, tự do, cạnh tranh tuyệt đối, phi nhà nước", "D. Đầy đủ, đồng bộ, hiện đại, hội nhập"], "answer": "D. Đầy đủ, đồng bộ, hiện đại, hội nhập", "letter": "D"}, {"id": 183, "cat": "dh13", "q": "Trong Ba đột phá chiến lược của Đại hội XIII, đột phá về \"Nguồn nhân lực & KHCN\" gắn việc phát triển nguồn nhân lực khoa học công nghệ, đổi mới sáng tạo với yếu tố nào?", "options": ["A. Cơ chế phân phối theo tem phiếu", "B. Chiến lược đóng cửa thị trường lao động", "C. Khát vọng phát triển đất nước", "D. Mục tiêu giảm quy mô công nghiệp hóa"], "answer": "C. Khát vọng phát triển đất nước", "letter": "C"}, {"id": 184, "cat": "dh13", "q": "Theo thông tin Đại hội XIII, trong giai đoạn nhiệm kỳ XII (2016–2020), lĩnh vực xã hội quốc tế nào của Việt Nam đã hoàn thành trước thời hạn?", "options": ["A. Hoàn thành mục tiêu trở thành nước thu nhập cao trước năm 2020", "B. Hoàn thành 100% tuyến đường sắt tốc độ cao Bắc – Nam", "C. Hoàn thành chuyển đổi số 100% doanh nghiệp nhỏ", "D. Hoàn thành nhiều Mục tiêu Thiên niên kỷ trước thời hạn"], "answer": "D. Hoàn thành nhiều Mục tiêu Thiên niên kỷ trước thời hạn", "letter": "D"}, {"id": 185, "cat": "dh14", "q": "Theo thông tin Đại hội XIV (1/2026), quy mô GDP của Việt Nam vượt 514 tỷ USD vào cuối nhiệm kỳ XIII tương đương gấp bao nhiêu lần so với năm 2020?", "options": ["A. Gấp 3,0 lần", "B. Gấp 1,48 lần", "C. Gấp 1,2 lần", "D. Gấp 2,5 lần"], "answer": "B. Gấp 1,48 lần", "letter": "B"}, {"id": 186, "cat": "dh14", "q": "Theo thông tin Đại hội XIV, ba đột phá chiến lược trong nhiệm kỳ XIII (thể chế, hạ tầng, nhân lực) đạt kết quả nổi bật nhất ở hai loại hình hạ tầng nào?", "options": ["A. Hạ tầng sản xuất thủ công nghiệp hộ gia đình", "B. Hạ tầng giao thông và hạ tầng số phát triển bứt phá", "C. Hạ tầng chợ truyền thống và kho lương thực bao cấp", "D. Hạ tầng thủy lợi cổ điển và hạ tầng khai khoáng than"], "answer": "B. Hạ tầng giao thông và hạ tầng số phát triển bứt phá", "letter": "B"}, {"id": 187, "cat": "dh14", "q": "Theo thông tin Đại hội XIV, tốc độ tăng trưởng GDP riêng năm 2025 đạt bao nhiêu phần trăm?", "options": ["A. 10,0%", "B. 6,20%", "C. 2,91%", "D. 8,02%"], "answer": "D. 8,02%", "letter": "D"}, {"id": 188, "cat": "dh14", "q": "Theo thông tin Đại hội XIV, tầm nhìn đến năm 2045 (kỷ niệm 100 năm thành lập nước) hướng tới xây dựng Việt Nam trở thành nước phát triển, thu nhập cao, gắn với tâm nguyện nào của Chủ tịch Hồ Chí Minh?", "options": ["A. Duy trì mức thu nhập trung bình ổn định", "B. Tự cấp tự túc hoàn toàn về mọi mặt", "C. Sánh vai với các cường quốc năm châu", "D. Hoàn thành cải cách ruộng đất toàn diện"], "answer": "C. Sánh vai với các cường quốc năm châu", "letter": "C"}, {"id": 189, "cat": "dh14", "q": "So sánh GDP bình quân đầu người cuối nhiệm kỳ XII (báo cáo tại ĐH XIII) và cuối nhiệm kỳ XIII (báo cáo tại ĐH XIV), con số này tăng từ mức nào lên mức nào?", "options": ["A. Từ 2.000 USD lên 4.200 USD", "B. Từ 1.500 USD lên 3.000 USD", "C. Từ 2.779 USD lên 5.026 USD", "D. Từ 3.500 USD lên 8.500 USD"], "answer": "C. Từ 2.779 USD lên 5.026 USD", "letter": "C"}, {"id": 190, "cat": "dh14", "q": "So sánh tỉ lệ bao phủ bảo hiểm y tế dân số tại báo cáo Đại hội XIII (cuối nhiệm kỳ XII) và báo cáo Đại hội XIV (cuối nhiệm kỳ XIII)?", "options": ["A. Giữ nguyên ở mức 90%", "B. Tăng từ trên 70% lên 85%", "C. Tăng từ 80% lên 90%", "D. Tăng từ trên 90% lên 95,2%"], "answer": "D. Tăng từ trên 90% lên 95,2%", "letter": "D"}, {"id": 191, "cat": "dh14", "q": "So sánh tỉ lệ hộ nghèo đa chiều giai đoạn 2022–2025 được nêu trong tài liệu Đại hội XIV?", "options": ["A. Giảm từ 6,5% (2022) xuống 3,0% (2025)", "B. Giảm từ 4,2% (2022) xuống 1,3% (2025)", "C. Giảm từ 3,0% (2022) xuống 2,5% (2025)", "D. Giảm từ 8,0% (2022) xuống 4,2% (2025)"], "answer": "B. Giảm từ 4,2% (2022) xuống 1,3% (2025)", "letter": "B"}, {"id": 192, "cat": "dh14", "q": "Trong Sáu nhiệm vụ trọng tâm của Đại hội XIV, nội dung nào xếp ở vị trí số 1?", "options": ["A. Xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh toàn diện; nâng cao năng lực lãnh đạo, cầm quyền của Đảng", "B. Giảm quy mô đầu tư công cho hạ tầng giao thông", "C. Xóa bỏ hoàn toàn thuế thu nhập doanh nghiệp", "D. Tập trung xuất khẩu nông sản thô"], "answer": "A. Xây dựng, chỉnh đốn Đảng và hệ thống chính trị trong sạch, vững mạnh toàn diện; nâng cao năng lực lãnh đạo, cầm quyền của Đảng", "letter": "A"}, {"id": 193, "cat": "dh14", "q": "Theo thông tin Đại hội XIV, giai đoạn định hướng phát triển mới mà Đại hội XIV mở ra là giai đoạn nào và tầm nhìn đến năm nào?", "options": ["A. Giai đoạn 2021–2025 và tầm nhìn đến năm 2035", "B. Giai đoạn 2025–2030 và tầm nhìn đến năm 2050", "C. Giai đoạn 2026–2030 và tầm nhìn đến năm 2045", "D. Giai đoạn 2026–2035 và tầm nhìn đến năm 2060"], "answer": "C. Giai đoạn 2026–2030 và tầm nhìn đến năm 2045", "letter": "C"}, {"id": 194, "cat": "dh14", "q": "Trong bối cảnh trong nước tại Đại hội XIV, yêu cầu đặt ra để vượt qua nguy cơ tụt hậu công nghệ và bẫy thu nhập trung bình là gì?", "options": ["A. Thu hẹp hội nhập quốc tế để bảo hộ doanh nghiệp nội địa", "B. Giữ nguyên tư duy cũ và hành động thận trọng, chậm rãi", "C. Đổi mới tư duy, hành động mạnh mẽ, quyết liệt, đột phá, hiệu quả", "D. Hạn chế ứng dụng trí tuệ nhân tạo và công nghệ số"], "answer": "C. Đổi mới tư duy, hành động mạnh mẽ, quyết liệt, đột phá, hiệu quả", "letter": "C"}, {"id": 195, "cat": "dh14", "q": "Ba đột phá chiến lược của Đại hội XIV bao gồm những trụ cột nào?", "options": ["A. Nông nghiệp hữu cơ; Du lịch biển đảo; Xuất khẩu lao động", "B. Quốc hữu hóa ngân hàng; Bao cấp lương thực; Cải cách hành chính cấp xã", "C. Thể chế phát triển; Nguồn nhân lực chất lượng cao; Kết cấu hạ tầng đồng bộ (giao thông đa phương thức, công nghệ, chuyển đổi số, chuyển đổi xanh)", "D. Đầu tư công nghiệp nặng; Hạn chế kinh tế tư nhân; Phát triển hợp tác xã"], "answer": "C. Thể chế phát triển; Nguồn nhân lực chất lượng cao; Kết cấu hạ tầng đồng bộ (giao thông đa phương thức, công nghệ, chuyển đổi số, chuyển đổi xanh)", "letter": "C"}, {"id": 196, "cat": "dh14", "q": "Sự khác biệt về tổng số đại biểu tham dự giữa Đại hội XIII (2021) và Đại hội XIV (2026) theo hai tài liệu tóm tắt là bao nhiêu?", "options": ["A. Đại hội XIII có 1.587 đại biểu; Đại hội XIV có 1.586 đại biểu", "B. Đại hội XIII có 1.586 đại biểu; Đại hội XIV có 1.587 đại biểu", "C. Đại hội XIII có 1.500 đại biểu; Đại hội XIV có 1.600 đại biểu", "D. Cả hai Đại hội đều có đúng 1.587 đại biểu"], "answer": "A. Đại hội XIII có 1.587 đại biểu; Đại hội XIV có 1.586 đại biểu", "letter": "A"}, {"id": 197, "cat": "dh14", "q": "Trong nhiệm kỳ Đại hội XIV, lĩnh vực chuyển đổi kép nào được nhấn mạnh trong đột phá về kết cấu hạ tầng đồng bộ?", "options": ["A. Chuyển đổi tiền tệ và chuyển đổi thương mại", "B. Chuyển đổi số và chuyển đổi xanh", "C. Chuyển đổi cơ cấu nông nghiệp và chuyển đổi hành chính", "D. Chuyển đổi giáo dục và chuyển đổi dân số"], "answer": "B. Chuyển đổi số và chuyển đổi xanh", "letter": "B"}, {"id": 198, "cat": "dh14", "q": "Khác với Đại hội XIII nhấn mạnh \"kiểm soát dịch bệnh, phục hồi kinh tế\", nhiệm vụ kinh tế tại Đại hội XIV nhấn mạnh vai trò đột phá của thành phần kinh tế nào trong nền KTTT định hướng XHCN hiện đại?", "options": ["A. Kinh tế tập thể là động lực duy nhất", "B. Kinh tế tư nhân là động lực quan trọng nhất", "C. Kinh tế tự cung tự cấp là trọng tâm", "D. Kinh tế có vốn nước ngoài là nền tảng chủ đạo duy nhất"], "answer": "B. Kinh tế tư nhân là động lực quan trọng nhất", "letter": "B"}, {"id": 199, "cat": "dh14", "q": "Đại hội XIII và Đại hội XIV đều có đại biểu đại diện cho khoảng bao nhiêu đảng viên trên cả nước?", "options": ["A. Hơn 4 triệu đảng viên", "B. Hơn 8 triệu đảng viên", "C. Hơn 3 triệu đảng viên", "D. Hơn 5 triệu đảng viên"], "answer": "D. Hơn 5 triệu đảng viên", "letter": "D"}];
